        const _thrownQuan = thrownObj ? thrownObj.quan : undefined;
        const _coinWholeThrow = ((thrownObj?.oclass | 0) === OCLASS_COIN && thrownObj !== u.uquiver);
        const _thrownSplits = !_coinWholeThrow && (_thrownQuan === undefined || (_thrownQuan | 0) > 1);
