    u.uz0 = { dnum: oldUz.dnum, dlevel: oldUz.dlevel };
    u.uz = { dnum: newlevel.dnum | 0, dlevel: newlevel.dlevel | 0 };
    u.utolev = { dnum: u.uz.dnum, dlevel: u.uz.dlevel };
