/* C ref: cmd.c:3532-3679 dokeylist() — help menu item 'j', "list all keys and
 * their bindings, like dat/hh but dynamic".  GENERALCMD: no turn, no RNG. */
async function dokeylist() {
    const g = game;
    const keys_used = new Array(256).fill(false);
    const pfx_seen = new Array(256).fill(0);
    let key;

    /* NO_SIGNAL is not defined: ^C is claimed before anything else. */
    keys_used[0x03 /* C('c') */] = true;

    /* movement keys have been flagged in keys_used[]; clone them */
    const mov_seen = keys_used.slice();

    const num_pad = !!(g.Cmd && g.Cmd.num_pad);
    let spkey_gap = false;
    for (const mk of MISC_KEYS) {
        if (mk.numpad && !num_pad)
            continue;
        const j = mk.nhkf;
        key = spkey_of(j);
        if (key && !mov_seen[key] && !pfx_seen[key]) {
            keys_used[key] = true;
            pfx_seen[key] = j;
        } else {
            spkey_gap = true;
        }
    }

    const datawin = [];
    datawin.push('');
    datawin.push(`${_pad_r('', 7)} ${'    Full Current Key Bindings List'}`);
    for (const extcmd of EXTCMDLIST)
        if (spkey_gap || !keylist_func_has_key(extcmd, keys_used)) {
            datawin.push(`${_pad_r('', 7)} ${'(also commands with no key assignment)'}`);
            break;
        }

    /* directional keys */
    datawin.push('');
    datawin.push('Directional keys:');
    for (const ln of show_direction_keys('.', false))  /* '.'==self in direct'n grid */
        datawin.push(ln);

    let buf;
    if (!num_pad) {
        datawin.push('');
        datawin.push('Ctrl+<direction> will run in specified direction until something very');
        datawin.push(`${_pad_r('', 7)} ${'interesting is seen.'}`);
        buf = 'Shift';   /* append the rest below */
    } else {
        datawin.push('');
        buf = 'Meta';
    }
    buf += '+<direction> will run in specified direction until you encounter';
    datawin.push(buf);
    datawin.push(`${_pad_r('', 7)} ${'an obstacle.'}`);

    datawin.push('');
    datawin.push('Miscellaneous keys:');
    for (const mk of MISC_KEYS) {
        if (mk.numpad && !num_pad)
            continue;
        const j = mk.nhkf;
        key = spkey_of(j);
        if (key && !mov_seen[key] && pfx_seen[key] === j)
            datawin.push(`${_pad_l(key2txt(key), 7)} ${mk.desc}`);
    }
    /* last of the special keys (NO_SIGNAL undefined) */
    key = 0x03; /* C('c') */
    datawin.push(`${_pad_l(key2txt(key), 7)} interrupt: break out of NetHack (SIGINT)`);
    /* keyless special key commands, if any */
    if (spkey_gap) {
        for (const mk of MISC_KEYS) {
            if (mk.numpad && !num_pad)
                continue;
            const j = mk.nhkf;
            key = spkey_of(j);
            if (!key || pfx_seen[key] !== j) {
                /* lines up with the other unassigned commands which use
                 * "#%-20s ", but not with the other special keys */
                datawin.push(`${_pad_l(`[${spkey_name(j)}]`, 21)} ${mk.desc}`);
            }
        }
    }

    const IGNORECMD = WIZMODECMD | INTERNALCMD | MOVEMENTCMD;

    datawin.push('');
    for (const ln of show_menu_controls(true))
        datawin.push(ln);

    if (keylist_putcmds(datawin, true, GENERALCMD, IGNORECMD, keys_used)) {
        datawin.push('');
        datawin.push('General commands:');
        keylist_putcmds(datawin, false, GENERALCMD, IGNORECMD, keys_used);
    }
    if (keylist_putcmds(datawin, true, 0, GENERALCMD | IGNORECMD, keys_used)) {
        datawin.push('');
        datawin.push('Game commands:');
        keylist_putcmds(datawin, false, 0, GENERALCMD | IGNORECMD, keys_used);
    }
    if (wizard() && keylist_putcmds(datawin, true, WIZMODECMD, INTERNALCMD, keys_used)) {
        datawin.push('');
        datawin.push('Debug mode commands:');
        keylist_putcmds(datawin, false, WIZMODECMD, INTERNALCMD, keys_used);
    }

    await display_text_window(datawin);
}
