const W_SADDLE_MASK_ST = 0x00100000;
/* C hack.c:xytodir — index of <x,y> in the xdir[]/ydir[] direction tables. */
function _st_xytodir(x, y) {
    for (let dd = 0; dd < N_DIRS; dd++)
        if (x === xdir[dd] && y === ydir[dd])
            return dd;
    return DIR_ERR;
}
/* C mondata.h throws_rocks(ptr) — (mflags2 & M2_ROCKTHROW). */
const _ST_M2_ROCKTHROW = 0x08000000;
function _st_throws_rocks(ptr) { return ((ptr?.mflags2 | 0) & _ST_M2_ROCKTHROW) !== 0; }
