    const carried_ball = !!(uball && (uball.where | 0) === 3 /* OBJ_INVENT, obj.h */);
    /* C ball.c:998 — `forward = carried(uball) && (uwep == uball || !uwep
     *                             || !rn2(3));` */
    const forward = carried_ball
        && (u.uwep === uball || !u.uwep || !rn2(3));
