        return;
    if (poly_when_stoned(_hero_youmonst().data) && await polymon(PM_STONE_GOLEM))
        return;
    await urgent_pline('You turn to stone...');
    await flush_pending_messages();
    game.svk ||= {};
    game.svk.killer ||= {};
    game.svk.killer.format = KILLED_BY;
