// C ref: insight.c mstatusline() — monster status line for stethoscope/probing.
export function mstatusline(mtmp) {
    const g = game;
    const u = g.u || {};
    const alignment = _mon_aligntyp_local(mtmp);
    let info = '';

    if (mtmp.mtame) {
        info += ', tame';
        if (wizard()) {
            info += _Sprintf_local(' (%d', mtmp.mtame);
            if (!mtmp.isminion)
                info += _Sprintf_local('; hungry %ld; apport %d',
                    _EDOG_local(mtmp).hungrytime, _EDOG_local(mtmp).apport);
            info += ')';
        }
    } else if (mtmp.mpeaceful)
        info += ', peaceful';

    if (mtmp.data && mtmp.data.pmidx === _PM_LONG_WORM) {
        let nsegs = _count_wsegs_local(mtmp);
        if (!nsegs) {
            info += ', single segment';
        } else {
            ++nsegs;
            let segndx = _wseg_at_local(mtmp, g.gb?.bhitpos?.x, g.gb?.bhitpos?.y);
            info += _Sprintf_local(', %d%s of %d segments',
                segndx, _ordin_local(segndx), nsegs);
        }
    }

    /* C insight.c:3328 `ismnum(mtmp->cham) && mtmp->data != &mons[mtmp->cham]`
       — a permonst POINTER comparison against the mons[] row for the innate
       form, i.e. "current form differs from innate form?". monsPack.mons[i]
       is a raw JSON row, never the object hanging off mtmp.data (which
       js/makemon.js permonstTemplate() mints fresh per call), so `!==` here
       was unconditionally true and the guard never blocked. Ported as the
       index comparison the pointer test means; a null mtmp.data reads as -1
       so it stays != cham, matching C's NULL != &mons[cham]. */
    if (_ismnum_local(mtmp.cham)
        && (mtmp.data ? (mtmp.data.pmidx | 0) : -1) !== (mtmp.cham | 0))
        info += ', shapechanger';

    if (mtmp.meating)
        info += ', eating';

    if (mtmp.mundetected || mtmp.m_ap_type
        || _visible_region_at(g.gb?.bhitpos?.x, g.gb?.bhitpos?.y))
        _mhidden_description_local(mtmp, _MHID_PREFIX | _MHID_ARTICLE | _MHID_ALTMON | _MHID_REGION, info);

    if (mtmp.mcan) info += ', cancelled';
    if (mtmp.mconf) info += ', confused';
    if (mtmp.mblinded || !mtmp.mcansee) info += ', blind';
    if (mtmp.mstun) info += ', stunned';
    if (mtmp.msleeping) info += ', asleep';
    else if (mtmp.mfrozen || !mtmp.mcanmove) info += ", can't move";
    else if ((mtmp.mstrategy & STRAT_WAITMASK) !== 0) info += ', meditating';

    if (mtmp.mflee) info += ', scared';
    if (mtmp.mtrapped) info += ', trapped';
    if (mtmp.mspeed) {
        info += (mtmp.mspeed === _MFAST) ? ', fast'
              : (mtmp.mspeed === _MSLOW) ? ', slow'
              : ', [? speed]';
    }
    if (mtmp.minvis) info += ', invisible';

    if (mtmp === u.ustuck) {
        let pm = u.ustuck.data;
        info += u.uswallow ? (_digests(pm) ? ', digesting you'
                               : (_is_animal_local(pm) && !_enfolds_local(pm))
                                 ? ', swallowing you'
                                 : ', engulfing you')
                 : (!_sticks() ? ', holding you'
                               : ', held by you');
    }

    if (mtmp === u.usteed) {
        info += ', carrying you';
        let HWounded = u.uprops?.[WOUNDED_LEGS]?.intrinsic | 0;
        let EWounded = u.uprops?.[WOUNDED_LEGS]?.extrinsic | 0;
        if (EWounded || HWounded) {
            let legs = (EWounded & _BOTH_SIDES);
            let what = _mbodypart_local(mtmp, _LEG);
            if (legs === _BOTH_SIDES)
                what = makeplural(what);
            info += _Sprintf_local(', injured %s', what);
        }
    }

    if (mtmp.mleashed)
        info += ', leashed';

    /* C insight.c mstatusline: x_monnam(mtmp, ARTICLE_YOUR, ...).  This used to
     * call the file-local `_x_monnam_local` below, whose whole article handling
     * is three string prefixes -- so ARTICLE_YOUR printed "your " for ANY
     * monster.  C's x_monnam opens with `if (article == ARTICLE_YOUR &&
     * !mtmp->mtame) article = ARTICLE_THE;` (do_name.c:849), and js/mhitm.js's
     * x_monnam -- imported at the top of this file and used by the rest of the
     * tree -- has that line.  Measured on seed5002 segment 1 step 97: C
     * "Status of the small mimic", this port "Status of your small mimic". */
    let monnambuf = x_monnam(mtmp, _ARTICLE_YOUR, null,
        _SUPPRESS_IT | _SUPPRESS_INVISIBLE, false);

    pline('Status of %s (%s, %s):  Level %d  HP %d(%d)  AC %d%s.',
        monnambuf, _align_str(alignment), _size_str_local(mtmp.data?.msize),
        mtmp.m_lev, mtmp.mhp, mtmp.mhpmax, find_mac(mtmp), info);
}

// ── mstatusline local helpers / stubs ──
const _PM_LONG_WORM = 114;
const _MFAST = 2;
const _MSLOW = 1;
/* mstatusline tests monst.h:177 STRAT_WAITMASK = STRAT_CLOSE|STRAT_WAITFORU
 * = 0x10000000|0x20000000; the removed local `_STRAT_WAITMASK` held 0x44,
 * which is the unrelated monflag.h M3_WAITFORU|M3_CLOSE pair.  Use the
 * const.js export (already imported at the top of this file). */
const _MHID_PREFIX = 1;
const _MHID_ARTICLE = 2;
const _MHID_ALTMON = 4;
const _MHID_REGION = 8;
const _BOTH_SIDES = (0x00020000 | 0x00040000); /* prop.h LEFT_SIDE|RIGHT_SIDE */
const _LEG = 9;
const _ARTICLE_YOUR = 3;
const _SUPPRESS_IT = 0x01;
const _SUPPRESS_INVISIBLE = 0x02;
function _mon_aligntyp_local(mtmp) { return mon_aligntyp_real(mtmp); }
function _count_wsegs_local(mtmp) { return count_wsegs_real(mtmp); }
function _wseg_at_local(mtmp, x, y) { return 1; }
function _enfolds_local(data) { return !!data && !!attacktype_fordmg(data, 11, 28); }
function _mhidden_description_local(mtmp, flags, buf) { /* no-op */ }
function _size_str_local(msize) { return 'medium'; }
function _mbodypart_local(mtmp, part) { return 'leg'; }
function _ismnum_local(pm) { return Number.isInteger(pm) && pm >= 0; }
function _EDOG_local(mtmp) { return mtmp?.mextra?.edog || {}; }
/* C mondata.h:66 — is_animal(ptr) = ((ptr->mflags1 & M1_ANIMAL) != 0L).
 * monflag.h:103 M1_ANIMAL = 0x00040000 (0x00000001 is M1_FLY). */
const _IS_ANIMAL_M1_ANIMAL = 0x00040000;
function _is_animal_local(data) { return data ? (data.mflags1 & _IS_ANIMAL_M1_ANIMAL) !== 0 : false; }
function _Sprintf_local(fmt) {
    let result = fmt;
    let ai = 1;
    let args = arguments;
    result = result.replace(/%s|%ld|%d/g, function() { return String(args[ai++]); });
    return result;
}
/* _x_monnam_local / _find_mac_local RETIRED (2026-08-17): both were stubs that
 * shadowed a complete shared port -- js/mhitm.js x_monnam and js/trap.js
 * find_mac -- and mstatusline was their only caller.  `_find_mac_local` returned
 * a constant 0, so every monster's status line read "AC 0" (C: AC 7 for the
 * small mimic of seed5002 segment 1 step 97). */
function _ordin_local(n) {
    const dd = n % 10;
    if (dd === 0 || dd > 3 || Math.trunc((n % 100) / 10) === 1) return 'th';
    else if (dd === 1) return 'st';
    else if (dd === 2) return 'nd';
    else return 'rd';
}

/* ════════════════════════════════════════════════════════════════════════
 * TINNING KIT — C apply.c:2167 tinnable() / apply.c:2177 use_tinning_kit(),
 * plus the corpsecheck==2 half of C eat.c:3579 floorfood().
 *
 * doapply's TINNING_KIT arm (apply.c:4294) did not exist, so an applied
 * tinning kit fell through to the switch default and printed
 * "Sorry, I don't know how to use that." — the JS-REFUSES-C-ACTS class.
 * On a hero carrying no tinnable corpse (which is every Archeologist at
 * turn 1, the kit being a fixed u_init.c slot) C's whole behaviour is:
 *   use_tinning_kit -> floorfood("tin", 2) -> nothing on the floor ->
 *   getobj("tin", tin_ok, GETOBJ_NOFLAGS) -> nothing suggested ->
 *   invent.c:1913 You("don't have anything %sto %s.", "", "tin")
 * i.e. "You don't have anything to tin." — and, because use_tinning_kit is
 * `void`, doapply's `res` is STILL ECMD_TIME, so the failed apply SPENDS
 * THE TURN.  Both halves matter: on corpus-generated/v5/probe-mechanism the
 * turn C takes here is what puts "The newt bites!" on the same topline.
 * ════════════════════════════════════════════════════════════════════════ */
/* C apply.c:2167 tinnable(struct obj *corpse) */
function tinnable(corpse) {
    if (corpse.oeaten) return false;
    if (!mons_cnutrit(corpse.corpsenm | 0)) return false;
    return true;
}
/* C eat.c:3560 tin_ok — the getobj callback for the object to be tinned.
 * GETOBJ_* here are js/const.js's numbering (0..5), not C's (-3..2). */
function tin_ok(obj) {
    if (!obj)
        return (game._getobj_else | 0) ? GETOBJ_EXCLUDE_NONINVENT : GETOBJ_EXCLUDE;
    if ((obj.oclass | 0) !== OCLASS_FOOD) return GETOBJ_EXCLUDE;
    if ((obj.otyp | 0) !== _AP_CORPSE_OTYP || !tinnable(obj))
        return GETOBJ_EXCLUDE_SELECTABLE;
    return GETOBJ_SUGGEST;
}
/* C eat.c:3579 floorfood(verb, corpsecheck) with verb=="tin", corpsecheck==2.
 * Mirrors the feeding branch of eat.js floorfood():
 * scan the hero's tile for a tinnable corpse and offer each in turn, then fall
 * through to the inventory getobj. */
async function floorfood_tin() {
    const g = game;
    const u = g.u || {};
    /* C eat.c:3591 getobj_else = 0. */
    g._getobj_else = 0;
    /* C eat.c:3597-3601 skipfloor guards.  `feeding` is false for "tin", so the
     * usteed and metallivorous arms (eat.c:3603-3670) are C-unreachable here;
     * only menu_requested / can_reach_floor / pool-or-lava remain, and this
     * port models neither levitation nor menu_requested beyond the flag. */
    if (!g.iflags?.menu_requested) {
        const ux = u.ux | 0, uy = u.uy | 0;
        let otmp = g.level?.levelObjects?.[ux]?.[uy] ?? null;
        while (otmp) {
            const next = otmp.nexthere ?? null;
            /* C eat.c:3677-3679 corpsecheck arm:
             *   otmp->otyp == CORPSE && (corpsecheck == 1 || tinnable(otmp)) */
            if ((otmp.otyp | 0) === _AP_CORPSE_OTYP && tinnable(otmp)) {
                /* C eat.c:3688-3694 — a cockatrice corpse is fatal to touch
                 * BEFORE the question is asked, and floorfood returns NULL.
                 * KNOWN GAP (the same one recorded at the look_here pile scan,
                 * cmd.js:27504): feel_cockatrice()'s instapetrify is not ported
                 * on a live floor path, so the return is faithful and the death
                 * is not.  No corpus session reaches it. */
                if (will_feel_cockatrice(otmp, false))
                    return null;
                const one = ((otmp.quan == null ? 1 : (otmp.quan | 0)) === 1);
                const verb = (one ? 'is' : 'are');
                const tail = one ? 'it' : 'one';
                const qbuf = `There ${verb} ${_drop_doname(otmp)} here; tin ${tail}?`;
                const cc = await yn_function(qbuf, 'ynq', 'n');
                if (cc === 'y') return otmp;
                if (cc === 'q') { g._pending_message = ''; return null; }
                g._getobj_else = (g._getobj_else | 0) + 1;
                g._pending_message = '';
            }
            otmp = next;
        }
    }
    /* C eat.c:3715 — corpsecheck == 2 → getobj(verb, tin_ok, GETOBJ_NOFLAGS). */
    const otmp = await getObjFromGetobj('tin', tin_ok, GETOBJ_NOFLAGS);
    /* C eat.c:3721-3726 — the post-getobj corpsecheck re-test. */
    if (otmp && ((otmp.otyp | 0) !== _AP_CORPSE_OTYP || !tinnable(otmp))) {
        await You_cant('tin that!');
        return null;
    }
    g._getobj_else = 0;
    return otmp;
}
const _UTK_TIN = 296; /* objects.h TIN — same literal js/mklev.js:391, js/eat.js */
/* C apply.c:2177 use_tinning_kit(struct obj *obj) — `void`; the caller's `res`
 * stays ECMD_TIME on every path, including the ones that print a refusal. */
async function use_tinning_kit(obj) {
    const g = game;
    const u = g.u || {};
    /* C apply.c:2185-2188 */
    if ((obj.spe | 0) <= 0) {
        await pline('You seem to be out of tins.');
        return;
    }
    /* C apply.c:2189-2190 */
    const corpse = await floorfood_tin();
    if (!corpse) return;
    /* C apply.c:2191-2194 — `something` is decl.c's "something". */
    if (corpse.oeaten) {
        await pline('You cannot tin something which is partly eaten.');
        return;
    }
    const mptr = permonstTemplate(corpse.corpsenm | 0);
    /* C apply.c:2196-2210 — tinning a cockatrice bare-handed. */
    if (sr_touch_petrifies_ptr(mptr) && !_uprop_active('STONE_RES') && !u.uarmg) {
        const corpse_name = an(cxname(corpse));
        let kbuf;
        if (poly_when_stoned(_hero_youmonst().data)) {
            await pline(`You tin ${corpse_name} without wearing gloves.`);
            kbuf = '';
        } else {
            await pline(`Tinning ${corpse_name} without wearing gloves is a fatal mistake...`);
            kbuf = `trying to tin ${corpse_name} without gloves`;
        }
        await instapetrify(kbuf);
    }
    /* C apply.c:2211-2217 — the Rider arm.  UNPORTED: revive_corpse() has no
     * binding in this tree and a Rider corpse cannot exist before the Rider is
     * killed, which no session in either corpus does.  Left as C's next test
     * rather than guessed at. */
    /* C apply.c:2218-2221 */
    if (mons_cnutrit(corpse.corpsenm | 0) === 0) {
        await pline("That's too insubstantial to tin.");
        return;
    }
    /* C apply.c:2222-2254 — consume a charge, mksobj(TIN), transfer corpsenm /
     * BUC / weight, set_tin_variety(HOMEMADE_TIN), use up the corpse and
     * hold_another_object() the tin.  hold_another_object (invent.c:1208, now
     * ported at js/hold_another_object.js) was the missing callee; it is
     * reached only when the hero actually SELECTS a tinnable corpse at the
     * prompt above, which zero of the 44 public and 688 train sessions do. */
    const can = await mksobj(_UTK_TIN, false, false);
    if (can) {
        can.corpsenm = corpse.corpsenm | 0;
        can.cursed = obj.cursed;
        can.blessed = obj.blessed;
        can.owt = weight(can);
        can.known = 1;
        /* C apply.c:2229-2230 — "Mark tinned tins. No spinach allowed..." */
        set_tin_variety(can, HOMEMADE_TIN);
        if ((corpse.where | 0) === 3 /* OBJ_INVENT */) {
            if (corpse.unpaid) {
                const shkp = shop_keeper((in_rooms(u.ux, u.uy, SHOPBASE) || [])[0]);
                await verbalize('You tin it, you bought it!');
                void shkp;
            }
            await useup(corpse);
        } else {
            if (costly_spot(corpse.ox | 0, corpse.oy | 0) && !corpse.no_charge) {
                const shkp = shop_keeper((in_rooms(corpse.ox | 0, corpse.oy | 0, SHOPBASE) || [])[0]);
                await verbalize('You tin it, you bought it!');
                void shkp;
            }
            await useupf(corpse, 1);
        }
        await hold_another_object(can, 'You make, but cannot pick up, %s.', (await doname(can)), null);
    } else {
        /* C apply.c:2253 impossible("Tinning failed.") — mksobj(TIN,...)
         * cannot fail (TIN is never genocided/gone), so this is C's
         * defensive-only branch; kept as a named no-op rather than faked. */
    }
}

/* ════════════════════════════════════════════════════════════════════════
 * BULLWHIP — C apply.c:2955 use_whip().  doapply's BULLWHIP arm
 * (apply.c:4265-4266) did not exist, so an applied bullwhip fell to the
 * switch default's "Sorry, I don't know how to use that." — 4 of the 16
 * remaining JS-REFUSES-C-ACTS render-first points on train (gen145 and
 * gen215, both step 282, both C="In what direction?" then C="Snap!").
 * ════════════════════════════════════════════════════════════════════════ */
async function use_whip(obj) {
    const g = game;
    const u = g.u = g.u || {};
    const msg_snap = 'Snap!';
    const res = ECMD_OK;

    /* C apply.c:2964-2971 — applying a bullwhip that is not the wielded weapon
     * wields it first and re-queues the apply.  CORRECTED 2026-09-05: the
     * comment this replaced claimed "wield_tool() has no real binding here",
     * citing a stale js/eat.js line number for a DIFFERENT (stub) definition.
     * js/cmd.js's OWN wield_tool (this file, ~line 42172) is a full port of
     * wield.c:683 and is already the live implementation dorub() dispatches
     * through for its own `obj != uwep` arm (apply.c:1806-1809) — the exact
     * same C idiom. There is no reason to special-case bullwhip to a refusal
     * C never gives: rebound to the same idiom dorub already proves out. */
    if (obj !== u.uwep) {
        if (await wield_tool(obj, 'lash')) {
            cmdq_add_ec(CQ_CANNED, 'doapply');
            cmdq_add_key(CQ_CANNED, obj.invlet | 0);
            return ECMD_TIME;
        }
        return res;
    }
    /* C apply.c:2972-2973 — getdir; a quitchar cancels.  js/lock.js getdir()
     * is the full port (movecmd + confdir + cmdassist). */
    if (!(await getdir(null)))
        return res | ECMD_CANCEL;

    /* C apply.c:2975-2987 — u.uswallow is out of scope here (the swallowed arm
     * only prints "There is not enough room..." below); confdir() already ran
     * inside getdir(). */
    const rx = (u.ux | 0) + (u.dx | 0);
    const ry = (u.uy | 0) + (u.dy | 0);
    if (!isok(rx, ry)) {
        await pline('You miss.');
        return res;
    }
    const mtmp = m_at(rx, ry);

    /* C apply.c:2989-3002 — "fake some proficiency checks". */
    let proficient = 0;
    if (Role_if(PM_ARCHEOLOGIST)) ++proficient;
    const dex = acurr(u, A_DEX);
    if (dex < 6) proficient--;
    else if (dex >= 14) proficient += (dex - 14);
    if (_uprop_active('FUMBLING')) --proficient;
    if (proficient > 3) proficient = 3;
    if (proficient < 0) proficient = 0;

    /* C apply.c:3013 — u.dz < 0: flick a bug off the ceiling. */
    if ((u.dz | 0) < 0) {
        await pline(`You flick a bug off of the ${ceiling(u.ux | 0, u.uy | 0)}.`);
        return ECMD_TIME;
    }
    /* C apply.c:3019-3057 — self-hit / steed / pool arms.  UNPORTED: they need
     * kick_steed, fire_damage, pickup_object and losehp on a path no corpus
     * session takes (every recorded whip is a plain lateral flick).  C's own
     * ordering is preserved: the water/lava tests sit BEFORE these, and both
     * reduce to false on a room floor. */
    if (((u.dx | 0) === 0 && (u.dy | 0) === 0) || (u.dz | 0) > 0) {
        if (u.usteed && !rn2(proficient + 2)) {
            await pline(`You whip ${mon_nam(u.usteed)}!`);
            await kick_steed_cmd();
            return ECMD_TIME;
        }
        const dam = Math.max(1, rnd(2) + dbon() + (obj.spe | 0));
        await pline('You hit your foot with your bullwhip.');
        await losehp(dam, 'killed yourself with your bullwhip', NO_KILLER_PREFIX);
        return ECMD_TIME;
    }
    /* C apply.c:3061-3063 — (Fumbling || Glib) && !rn2(5): drop the whip.
     * The rn2(5) is C's, so it must only be drawn when the guard is true. */
    if ((_uprop_active('FUMBLING') || _uprop_active('GLIB')) && !rn2(5)) {
        await pline('The bullwhip slips out of your hand.');
        await dropx(obj);
        return ECMD_TIME;
    }
    /* C apply.c:3065-3122 — the TT_PIT arm. */
    if ((u.utrap | 0) && (u.utraptype | 0) === TT_PIT) {
        const tile = game.level?.at?.(rx, ry) || game.level?.locations?.[rx]?.[ry] || {};
        const boulder = sobj_at(475, rx, ry);
        const furniture = IS_FURNITURE(tile.typ | 0);
        let wrapped = boulder ? 'a boulder' : furniture ? 'something' : null;
        if (mtmp && (mtmp.data?.msize | 0) >= 2 && canspotmon(mtmp))
            wrapped = mon_nam(mtmp);
        if (!wrapped) {
            await pline(msg_snap);
            return ECMD_TIME;
        }
        await pline(`You wrap your bullwhip around ${wrapped}.`);
        if (proficient && rn2(proficient + 2)) {
            const landing = enexto_out(rx, ry, game.youmonst?.data || null);
            if (landing || !mtmp) {
                await pline('You yank yourself out of the pit!');
                await reset_utrap(true);
                const spot = landing || { x: rx, y: ry };
                await teleds(spot.x, spot.y, TELEDS_ALLOW_DRAG);
            } else {
                await pline(msg_snap);
            }
        } else {
            await pline('The whip slips free.');
        }
        if (mtmp) await wakeup(mtmp, true);
        return ECMD_TIME;
    }
    /* C apply.c:3123-3262 — whipattack: reveal / disarm / attack a monster. */
    if (mtmp) {
        const mwep = mtmp.mw || mtmp.mwep || mtmp.weapon || null;
        if (canspotmon(mtmp) && mwep) {
            const gotit = proficient > 0 && (!_uprop_active('FUMBLING') || !rn2(10));
            await pline(`You wrap your bullwhip around ${yname(mwep)}.`);
            if (gotit && mwelded(mwep)) {
                mwep.bknown = 1;
                await pline('It is welded to the monster\'s hand!');
            } else if (gotit) {
                obj_extract_self(mwep);
                await possibly_unwield(mtmp, false);
                setmnotwielded(mtmp, mwep);
                const landing = rn2(proficient + 1);
                if (landing === 2) {
                    await pline(`You yank ${yname(mwep)} to the floor.`);
                    place_object(mwep, u.ux | 0, u.uy | 0);
                    await stackobj(mwep);
                } else if (landing === 3) {
                    await pline(`You snatch ${yname(mwep)}!`);
                    await hold_another_object(mwep, 'You drop %s!', (await doname(mwep)), null);
                } else {
                    await pline(`You yank ${yname(mwep)} from ${mon_nam(mtmp)}.`);
                    await obj_no_longer_held(mwep);
                    place_object(mwep, mtmp.mx | 0, mtmp.my | 0);
                    await stackobj(mwep);
                }
            } else {
                await pline('The whip slips free.');
            }
            await wakeup(mtmp, true);
            return ECMD_TIME;
        }
        let do_snap = true;
        const protectedShape = !!(u.uprops?.[PROT_FROM_SHAPE_CHANGERS]?.intrinsic
            || u.uprops?.[PROT_FROM_SHAPE_CHANGERS]?.extrinsic);
        if (!canspotmon(mtmp)) {
            mtmp.mundetected = 0;
            const nowVisible = canspotmon(mtmp);
            if (nowVisible || !glyph_is_invisible_at(rx, ry)) {
                await pline('%s is there that you couldn\'t see.', nowVisible ? mon_nam(mtmp) : 'A monster');
                if (!nowVisible) map_invisible(rx, ry); else newsym(rx, ry);
            }
        } else if (M_AP_TYPE(mtmp) && !protectedShape && !sensemon(mtmp)) {
            seemimic(mtmp);
            do_snap = false;
        } else {
            await pline(`You flick your bullwhip towards ${mon_nam(mtmp)}.`);
        }
        await wakeup(mtmp, true);
        if (do_snap) await pline(msg_snap);
        return ECMD_TIME;
    }
    /* C apply.c:3264-3266 — air and water levels. */
    if (Is_airlevel(u.uz) || Is_waterlevel(u.uz)) {
        await pline('You snap your whip through thin air.');
        return ECMD_TIME;
    }
    /* C apply.c:3268 — the ordinary flick. */
    await pline(msg_snap);
    return ECMD_TIME;
}

/* ════════════════════════════════════════════════════════════════════════
 * GRAPPLING_HOOK — C apply.c:3729 use_grapple().  doapply's GRAPPLING_HOOK
 * arm (apply.c:4268-4270) did not exist at all, so applying one fell to the
 * switch default's "Sorry, I don't know how to use that."  Only the
 * wield-first arm (apply.c:3740-3748, the same wield_tool idiom as use_whip
 * and dorub above) is ported; the targeting/hook-and-pull body past the
 * `assert(obj == uwep)` is a separate packet (getpos, grapple_range,
 * can_grapple_location, the pull-object/pull-monster/pull-self ladder). */
const _AP_GRAPPLING_HOOK_OTYP = 260; /* objects.h GRAPPLING_HOOK */
async function use_grapple(obj) {
    const g = game;
    const u = g.u = g.u || {};
    const res = ECMD_OK;

    /* C apply.c:3737-3740 */
    if (u.uswallow) {
        await pline("There's not enough room here to use that.");
        return res;
    }
    /* C apply.c:3742-3749 — same wield_tool idiom as use_whip/dorub above. */
    if (obj !== u.uwep) {
        if (await wield_tool(obj, 'cast')) {
            cmdq_add_ec(CQ_CANNED, 'doapply');
            cmdq_add_key(CQ_CANNED, obj.invlet | 0);
            return ECMD_TIME;
        }
        return res;
    }
    /* C apply.c:3752-3830 — targeting and the pull ladder. */
    await pline('Where do you want to hit?');
    const cc = { x: u.ux | 0, y: u.uy | 0 };
    if ((await getpos(cc, true, 'the spot to hit')) < 0)
        return res | ECMD_CANCEL;
    const range = Math.max(Math.abs((cc.x | 0) - (u.ux | 0)),
                           Math.abs((cc.y | 0) - (u.uy | 0)));
    if (range > 4) {
        await pline('Too far!');
        return res;
    }
    if (!cansee(cc.x, cc.y)) {
        await You("can't see that spot.");
        return res;
    }
    const tohit = rn2(5);
    const target = m_at(cc.x, cc.y);
    if (target) {
        game.bhitpos = { x: cc.x | 0, y: cc.y | 0 };
        if ((target.data?.msize | 0) <= 1 && !rn2(4)) {
            await pline('You pull in %s!', mon_nam(target));
            await rloc_to(target, u.ux | 0, u.uy | 0);
        } else {
            await thitmonst(target, obj);
        }
        return ECMD_TIME;
    }
    const floorObj = sobj_at(cc.x, cc.y);
    if (floorObj && tohit === 1) {
        await pline('You snag an object from the floor!');
        obj_extract_self(floorObj);
        await hold_another_object(floorObj, 'You drop %s!', (await doname(floorObj)), null);
        return ECMD_TIME;
    }
    if (tohit === 2 || tohit === 3) {
        await You('are yanked toward the target!');
        await hurtle(Math.sign((cc.x | 0) - (u.ux | 0)),
                     Math.sign((cc.y | 0) - (u.uy | 0)), 1, false);
        return ECMD_TIME;
    }
    await pline(nothing_seems_to_happen);
    return ECMD_TIME;
}

/* C ref: rnd.c:298-309 shuffle_int_array(indices, count) — Fisher-Yates over
 * an int[], used once here (apply.c:2333) to randomise which properties an
 * uncursed/blessed unicorn horn fixes first. */
function shuffle_int_array(indices, count) {
    for (let i = count - 1; i > 0; i--) {
        const iswap = rn2(i + 1);
        if (iswap === i) continue;
        const tmp = indices[i];
        indices[i] = indices[iswap];
        indices[iswap] = tmp;
    }
}

/* C ref: apply.c:2259-2388 use_unicorn_horn(struct obj **optr).  `optr` is
 * never reassigned in C (no case sets *optr = 0), so this port takes the obj
 * directly — the caller's selObj identity is untouched either way.
 *
 * MEASURED on the doapply capture board: 58 of 59 recorded applications of an
 * uncursed/blessed horn take the trouble_count==0 tail (0 RNG draws); 1 takes
 * the trouble-fixing path (shuffle + d() + rn2(), 3 draws, confirmed against
 * this port: shuffle rn2(2)=0 swaps the 2-item trouble_list, d(2,4)=8 (a
 * BLESSED horn), rn2(8)=5, val_limit=min(5,2)=2 — both troubles fixed).  0
 * records reach the CURSED branch. */
async function use_unicorn_horn(obj) {
    const u = game.u || {};
    if (obj && obj.cursed) {
        const lcount = rn1(90, 10);
        switch ((rn2(13) / 2) | 0) { /* case 6 is half as likely as the others */
        case 0: {
            const sickTimeout = _hprop(SICK) & TIMEOUT;
            await make_sick(sickTimeout ? (((sickTimeout / 3) | 0) + 1)
                                        : rn1(acurr(u, A_CON), 20),
                             xname(obj), true, SICK_NONVOMITABLE);
            break;
        }
        case 1:
            make_blinded(BlindedTimeout() + lcount, true);
            break;
        case 2: {
            const halluc = _hprop(HALLUC) && !_uprop_active('HALLUC_RES');
            if (!_hprop(CONFUSION))
                await You(`suddenly feel ${halluc ? 'trippy' : 'confused'}.`);
            make_confused((_hprop(CONFUSION) & TIMEOUT) + lcount, true);
            break;
        }
        case 3:
            make_stunned((_hprop(STUNNED) & TIMEOUT) + lcount, true);
            break;
        case 4:
            if (_hprop(VOMITING)) await potion_vomit();
            else await make_vomiting(14, false);
            break;
        case 5:
            await make_hallucinated((_hprop(HALLUC) & TIMEOUT) + lcount, true, 0);
            break;
        case 6:
            /* make_deaf() gives no feedback when already deaf. */
            if (_hero_Deaf())
                await pline('%s', nothing_seems_to_happen);
            await make_deaf((_hprop(DEAF) & TIMEOUT) + lcount, true);
            break;
        }
        return;
    }

    /* C apply.c:2308-2318 — TimedTrouble(P): P is nonzero and carries NO bits
     * outside TIMEOUT (no FROMOUTSIDE/FROMFORM flag) → P & TIMEOUT; else 0. */
    const _timedTrouble = (p) => (p && !(p & ~TIMEOUT)) ? (p & TIMEOUT) : 0;
    const troubleList = [];
    if (_timedTrouble(_hprop(SICK))) troubleList.push(SICK);
    /* apply.c:2312-2315 — BLINDED needs TimedTrouble(HBlinded) > u.ucreamed,
     * AND (not swallowed by an engulfer that blinds on AD_BLND). */
    if (_timedTrouble(_hprop(BLINDED)) > (u.ucreamed | 0)
        && !(u.uswallow
             && attacktype_fordmg((u.ustuck && u.ustuck.data) || null, _AT_ENGL, _AD_BLND)))
        troubleList.push(BLINDED);
    if (_timedTrouble(_hprop(HALLUC))) troubleList.push(HALLUC);
    if (_timedTrouble(_hprop(VOMITING))) troubleList.push(VOMITING);
    if (_timedTrouble(_hprop(CONFUSION))) troubleList.push(CONFUSION);
    if (_timedTrouble(_hprop(STUNNED))) troubleList.push(STUNNED);
    if (_timedTrouble(_hprop(DEAF))) troubleList.push(DEAF);

    const troubleCount = troubleList.length;
    if (troubleCount === 0) {
        await pline1(nothing_happens);
        return;
    } else if (troubleCount > 1) {
        shuffle_int_array(troubleList, troubleCount);
    }

    let valLimit = rn2(d(2, (obj && obj.blessed) ? 4 : 2));
    if (valLimit > troubleCount) valLimit = troubleCount;

    let didProp = 0;
    for (let val = 0; val < valLimit; val++) {
        const idx = troubleList[val];
        switch (idx) {
        case SICK:
            await make_sick(0, null, true, SICK_ALL);
            didProp++;
            break;
        case BLINDED:
            make_blinded(u.ucreamed | 0, true);
            didProp++;
            break;
        case HALLUC:
            await make_hallucinated(0, true, 0);
            didProp++;
            break;
        case VOMITING:
            await make_vomiting(0, true);
            didProp++;
            break;
        case CONFUSION:
            make_confused(0, true);
            didProp++;
            break;
        case STUNNED:
            make_stunned(0, true);
            didProp++;
            break;
        case DEAF:
            await make_deaf(0, true);
            didProp++;
            break;
        default:
            break; /* impossible("use_unicorn_horn: bad trouble? (%d)", idx); */
        }
    }

    if (didProp) {
        if (game.disp) game.disp.botl = 1;
    } else {
        await pline('%s', nothing_seems_to_happen);
    }
}
/* C ref: weapon.c:1019-1033 finish_towel_change(obj, newspe) — shared tail of
 * wet_a_towel/dry_a_towel, using the shared inventory refresh. */
function finish_towel_change(obj, newspe) {
    newspe = Math.min(newspe, 7);
    obj.spe = Math.max(newspe, 0);
    const u = game.u || {};
    if (obj === u.uwep)
        game.unweapon = !is_wet_towel(obj);
    /* carried(obj): use_towel only ever calls this on the hero's own
     * inventory towel (doapply's getobj selection), so C's carried(obj) test
     * is unconditionally true on every reachable call site here. */
    update_inventory();
}
/* C ref: weapon.c:1066-1085 dry_a_towel(obj, amt, verbose).  amt<0: decrement
 * by abs(amt); amt>=0: new value. */
function dry_a_towel(obj, amt, verbose) {
    const newspe = (amt < 0) ? (obj.spe | 0) + amt : amt;
    if (newspe < (obj.spe | 0)) {
        if (verbose) {
            /* carried(obj) — see finish_towel_change's note. */
            pline(`${Yobjnam2(obj, null)} dries${!newspe ? ' out' : ''}.`);
        }
    }
    if (newspe !== (obj.spe | 0))
        finish_towel_change(obj, newspe);
}

/* C ref: apply.c:111-193 use_towel(struct obj *obj).
 *
 * MEASURED on the doapply capture board: all 28 recorded towel applications
 * take the tail "Your face and hands are already clean." (ECMD_OK, 0 RNG) —
 * freehand() true, not ublindf, not cursed, Glib false, u.ucreamed 0.  Every
 * other arm (cursed/Glib/creamed/blindfold-push) is ported for fidelity but
 * unexercised by any record we hold. */
async function use_towel(obj) {
    const u = game.u || {};
    const dryingFeedback = (obj === u.uwep);
    if (!freehand()) {
        await You(`have no free ${body_part(HAND)}!`);
        return ECMD_OK;
    } else if (obj === u.ublindf) {
        await You("cannot use it while you're wearing it!");
        return ECMD_OK;
    } else if (obj.cursed) {
        switch (rn2(3)) {
        case 2: {
            const old = _hprop(GLIB) & TIMEOUT;
            make_glib(old + rn1(10, 3)); /* + 3..12 */
            await Your(`${makeplural_objnam(body_part(HAND))} `
                       + `${old ? 'are filthier than ever' : 'get slimy'}!`);
            if (is_wet_towel(obj)) dry_a_towel(obj, -1, dryingFeedback);
            return ECMD_TIME;
        }
        case 1: {
            if (!u.ublindf) {
                const old = u.ucreamed | 0;
                u.ucreamed = old + rn1(10, 3);
                await pline(`Yecch!  Your ${body_part(FACE)} `
                            + `${old ? 'has more' : 'now has'} gunk on it!`);
                make_blinded(BlindedTimeout() + (u.ucreamed | 0) - old, true);
            } else {
                const ublindf = u.ublindf;
                const what = (ublindf.otyp | 0) === 232 /* LENSES */
                    ? 'lenses'
                    : ((obj.otyp | 0) === (ublindf.otyp | 0)) ? 'other towel' : 'blindfold';
                if (ublindf.cursed) {
                    await You(`push your ${what} `
                              + `${rn2(2) ? 'cock-eyed' : 'crooked'}.`);
                } else {
                    const savedUblindf = ublindf;
                    await You(`push your ${what} off.`);
                    await Blindf_off(ublindf);
                    await dropx(savedUblindf);
                }
            }
            if (is_wet_towel(obj)) dry_a_towel(obj, -1, dryingFeedback);
            return ECMD_TIME;
        }
        case 0:
            break;
        }
    }

    if (_hprop(GLIB)) {
        make_glib(0);
        await You(`wipe off your ${!u.uarmg ? makeplural_objnam(body_part(HAND))
                                             : gloves_simple_name(u.uarmg)}.`);
        if (is_wet_towel(obj)) dry_a_towel(obj, -1, dryingFeedback);
        return ECMD_TIME;
    } else if (u.ucreamed) {
        /* C apply.c:173 — incr_itimeout(&HBlinded, (-1 * (int) u.ucreamed)). */
        incr_HBlinded(-1 * (u.ucreamed | 0));
        u.ucreamed = 0;
        /* C apply.c:175 tests `!Blinded` — the COMPOUND macro
         * ((HBlinded||EBlinded) && !BBlinded) — not `!HBlinded` (do.c's
         * wipeoff tests the raw intrinsic instead; these are two different
         * C functions).  _Blind_cmd() is this file's existing port of Blind. */
        if (!_Blind_cmd()) {
            await pline("You've got the glop off.");
            if (!gulp_blnd_check()) {
                set_HBlinded(1); /* set_itimeout(&HBlinded, 1L) */
                make_blinded(0, true);
            }
        } else {
            await Your('%s feels clean now.', body_part(FACE));
        }
        if (is_wet_towel(obj)) dry_a_towel(obj, -1, dryingFeedback);
        return ECMD_TIME;
    }

    await Your(`${body_part(FACE)} and ${makeplural_objnam(body_part(HAND))} `
               + 'are already clean.');
    return ECMD_OK;
}

const MAXLEASHED = 2; /* apply.c:762 #define MAXLEASHED 2 */
const LEASH_OTYP = 236; /* objects.h LEASH, resolved via tools/lib/c-const-resolve.mjs */
/* C ref: apply.c:697-702 number_leashed(void) — count invent LEASH objects
 * whose leashmon is set.  obj.leashmon has no writer anywhere in this port
 * yet (leashing a pet is unverified by any capture we hold — see
 * use_leash_core below), so this always counts 0 today; written to match C
 * rather than hardcoded, so a future leashmon writer arms it for free. */
function number_leashed() {
    let n = 0;
    for (let o = game.invent; o; o = o.nobj)
        if ((o.otyp | 0) === LEASH_OTYP && (o.leashmon | 0) !== 0) n++;
    return n;
}
/* C ref: apply.c:769-813 use_leash(struct obj *obj).
 *
 * MEASURED on the doapply capture board: all 8 recorded leash applications
 * (one per compass direction, an apparent direction-coverage probe) take the
 * "no creature there" tail — m_at(cc) is null in every recorded direction —
 * which returns ECMD_TIME with no RNG.  use_leash_core's monster-found body
 * (leashable/unsolid/nolimbs/has_head/l_monnam — none ported anywhere in this
 * tree) is therefore UNVERIFIED by any record we hold; left as a documented
 * gap below rather than guessed, matching this file's use_whip convention for
 * the same shape of unexercised branch. */
async function use_leash(obj) {
    const u = game.u || {};
    if (u.uswallow) {
        const ustuck = u.ustuck;
        await You_cant(!obj.leashmon
            ? `leash ${noit_mon_nam(ustuck)} from inside.`
            : ((obj.leashmon | 0) === ((ustuck && ustuck.m_id) | 0))
                ? `unleash ${noit_mon_nam(ustuck)} from inside.`
                : `unleash anything from inside ${noit_mon_nam(ustuck)}.`);
        return ECMD_OK;
    }
    if (!obj.leashmon && number_leashed() >= MAXLEASHED) {
        await You('cannot leash any more pets.');
        return ECMD_OK;
    }

    /* C cmd.c:3931-3951 get_adjacent_loc(NULL, NULL, u.ux, u.uy, &cc), inlined:
     * getdir() fail -> Never_mind, ECMD_OK; else compute cc, isok fail (no
     * emsg here) -> ECMD_OK. */
    if (!(await getdir(null))) {
        await pline1('Never mind.'); /* decl.c Never_mind, NOT flags.verbose-gated here */
        return ECMD_OK;
    }
    const ccx = (u.ux | 0) + (u.dx | 0), ccy = (u.uy | 0) + (u.dy | 0);
    if (!isok(ccx, ccy)) return ECMD_OK;

    if (u_at(ccx, ccy)) {
        if (u.usteed && (u.dz | 0) > 0) {
            /* C apply.c:800-803 — the mounted steed occupies the hero's
             * square when the downward direction is selected. */
            await use_leash_core(obj, u.usteed, ccx, ccy, true);
            return ECMD_TIME;
        }
        await pline('Leash yourself?  Very funny...');
        return ECMD_OK;
    }

    /* From here, a move is always used (apply.c:807 comment). */
    const mtmp = m_at(ccx, ccy);
    if (!mtmp) {
        await pline('There is no creature there.');
        unmap_invisible(ccx, ccy);
        return ECMD_TIME;
    }
    await use_leash_core(obj, mtmp, ccx, ccy, canspotmon(mtmp));
    return ECMD_TIME;
}
/* apply.c mondata.h macros use_leash_core needs, none ported elsewhere in
 * this tree (measured via grep before writing these): unsolid/nolimbs/
 * has_head are raw mflags1 bit tests, leashable composes them with a
 * PM_LONG_WORM check. */
const _M1_NOLIMBS = 0x00006000, _M1_NOHEAD = 0x00008000, _M1_UNSOLID = 0x00100000;
function _lsh_unsolid(ptr) { return ((ptr.mflags1 | 0) & _M1_UNSOLID) !== 0; }
function _lsh_nolimbs(ptr) { return ((ptr.mflags1 | 0) & _M1_NOLIMBS) === _M1_NOLIMBS; }
function _lsh_has_head(ptr) { return ((ptr.mflags1 | 0) & _M1_NOHEAD) === 0; }
function _lsh_leashable(mtmp) {
    return (mtmp.mnum | 0) !== PM_LONG_WORM
        && !_lsh_unsolid(mtmp.data)
        && (!_lsh_nolimbs(mtmp.data) || _lsh_has_head(mtmp.data));
}
/* C ref: do_name.c:1034 l_monnam(mtmp) — x_monnam(mtmp, ARTICLE_NONE, ...).
 * No port anywhere in this tree; Monnam (imported, mcastu.js) is this file's
 * existing x_monnam-family port and gives ARTICLE_THE ("the kitten"/"Fluffy"),
 * so stripping a leading "The "/"the " reproduces l_monnam's no-article form
 * for the unnamed case and is a no-op for a given-name pet (mon_nam already
 * omits the article for those — the same reason js/cmd.js:19700's Shk_Your
 * neighbour gives for its own simplification). */
function _lsh_lmonnam(mtmp) {
    return mon_nam(mtmp).replace(/^(the |The )/, '');
}
/* C ref: apply.c:816-863 use_leash_core. glyph_is_invisible (the !spotmon
 * guard's other half) has no port and is UNVERIFIED by any record here. */
async function use_leash_core(obj, mtmp, ccx, ccy, spotmon) {
    void ccx; void ccy;
    if (!spotmon) {
        await You(`fail to ${obj.leashmon ? 'un' : ''}leash something.`);
        /* C: map_invisible(cc->x, cc->y) — needs glyph_is_invisible's sibling
         * write path; not exercised by any record we hold. */
        return;
    }
    if (!mtmp.mtame) {
        await pline(`${Monnam(mtmp)} ${!obj.leashmon ? 'cannot be' : 'is not'} leashed!`);
        return;
    }
    if (!obj.leashmon) {
        if (mtmp.mleashed) {
            await pline(`This ${spotmon ? _lsh_lmonnam(mtmp) : 'creature'} is already leashed.`);
        } else if (_lsh_unsolid(mtmp.data)) {
            await pline('The leash would just fall off.');
        } else if (_lsh_nolimbs(mtmp.data) && !_lsh_has_head(mtmp.data)) {
            await pline(`${Monnam(mtmp)} has no extremities the leash would fit.`);
        } else if (!_lsh_leashable(mtmp)) {
            /* C: lmonnam gets " tail" appended when cc != mtmp's own square
             * (the not-on-its-own-square long-worm case), s_suffix'd. */
            let lmonnam = _lsh_lmonnam(mtmp);
            if (ccx !== (mtmp.mx | 0) || ccy !== (mtmp.my | 0))
                lmonnam = `${s_suffix(lmonnam)} tail`;
            await pline(`The leash won't fit onto ${spotmon ? 'your ' : ''}${lmonnam}.`);
        } else {
            await You(`slip the leash around ${spotmon ? 'your ' : ''}${_lsh_lmonnam(mtmp)}.`);
            mtmp.mleashed = 1;
            obj.leashmon = mtmp.m_id | 0;
            mtmp.msleeping = 0;
            update_inventory();
        }
        return;
    }
    /* obj.leashmon set: unleashing arm. */
    if ((obj.leashmon | 0) !== (mtmp.m_id | 0)) {
        await pline('This leash is not attached to that creature.');
    } else if (obj.cursed) {
        await pline_The('leash would not come off!');
        set_bknown(obj, 1);
    } else {
        mtmp.mleashed = 0;
        obj.leashmon = 0;
        update_inventory();
        await You(`remove the leash from ${spotmon ? 'your ' : ''}${_lsh_lmonnam(mtmp)}.`);
    }
}

/* C ref: apply.c:2584-2600 grease_ok — getobj callback for the nested "grease
 * what?" prompt use_grease raises. */
async function _grease_ok(obj) {
    if (!obj) return GETOBJ_SUGGEST;
    if ((obj.oclass | 0) === 12 /* COIN_CLASS */) return GETOBJ_EXCLUDE;
    if (inaccessible_equipment(obj, null, false)) return GETOBJ_EXCLUDE_INACCESS;
    return GETOBJ_SUGGEST;
}
/* C ref: apply.c:2603-2653 use_grease(struct obj *obj). */
async function use_grease(obj) {
    const u = game.u || {};
    if (_hprop(GLIB)) {
        await pline(`${_objnam_Tobjnam(obj, 'slip')} from your ${_ul_fingers_or_gloves(false)}.`);
        await dropx(obj);
        return ECMD_TIME;
    }
    if ((obj.spe | 0) > 0) {
        if (((obj.cursed | 0) || _uprop_active('FUMBLING')) && !rn2(2)) {
            consume_obj_charge(obj, true);
            await pline(`${_objnam_Tobjnam(obj, 'slip')} from your ${_ul_fingers_or_gloves(false)}.`);
            await dropx(obj);
            return ECMD_TIME;
        }
        const otmp = await getObjFromGetobj('grease', _grease_ok, GETOBJ_PROMPT);
        if (!otmp) return ECMD_CANCEL;
        if (!otmp.hands && inaccessible_equipment(otmp, 'grease', false)) return ECMD_OK;
        consume_obj_charge(obj, true);
        const oldglib = _hprop(GLIB) & TIMEOUT;
        if (!otmp.hands) {
            await You(`cover ${yname(otmp)} with a thick layer of grease.`);
            otmp.greased = 1;
            if ((obj.cursed | 0) && !_hero_verysmall_or_nohands_nohands_only()) {
                make_glib(oldglib + rn1(6, 10)); /* + 10..15 */
                await pline(`Some of the grease gets all over your ${_ul_fingers_or_gloves(true)}.`);
            }
        } else {
            make_glib(oldglib + rn1(11, 5)); /* + 5..15 */
            await You(`coat your ${_ul_fingers_or_gloves(true)} with grease.`);
        }
    } else {
        if (obj.known)
            await pline(`${_objnam_Tobjnam(obj, 'are')} empty.`);
        else
            await pline(`${_objnam_Tobjnam(obj, 'seem')} to be empty.`);
    }
    update_inventory();
    return ECMD_TIME;
}

/* C ref: makemon.c:2552-2597 bagotricks(struct obj *bag, boolean tipping,
 * int *seencount) — release monster(s) from a bag of tricks; returns the
 * number of monsters created. `tipping`/`seencount` are only meaningful to
 * pickup.c's #loot callers (tipping a container / emptying it entirely);
 * doapply's own call site (apply.c:4279-4280) always passes
 * `(obj, FALSE, (int *) 0)`, so this port keeps the two extra parameters
 * (for a future #loot caller) but doapply below calls it with tipping=false
 * and ignores the return. */
const _BOT_BAG_OF_TRICKS_OTYP = 220; /* objects.h BAG_OF_TRICKS */
async function bagotricks(bag, tipping, seencountRef) {
    const g = game;
    const u = g.u || {};
    let moncount = 0;
    if (!bag || (bag.otyp | 0) !== _BOT_BAG_OF_TRICKS_OTYP) {
        /* C: impossible("bad bag o' tricks"); -- never reached from doapply's
         * own dispatch, which only calls this with a real BAG_OF_TRICKS. */
        return moncount;
    }
    if ((bag.spe | 0) < 1) {
        /* C makemon.c:2561 — pline1((tipping && bag->cknown) ? "It's empty."
         * : nothing_happens); */
        await pline((tipping && bag.cknown) ? "It's empty." : nothing_happens);
        if (bag.dknown && g._oc_name_known && g._oc_name_known[_BOT_BAG_OF_TRICKS_OTYP]) {
            bag.cknown = 1;
            update_inventory();
        }
        return moncount;
    }
    let creatcnt = 1, seecount = 0;
    consume_obj_charge(bag, !tipping);
    if (!rn2(23))
        creatcnt += rnd(7);
    do {
        const mtmp = await mklev_makemon(null, u.ux | 0, u.uy | 0, 0 /* NO_MM_FLAGS */);
        if (mtmp) {
            ++moncount;
            if ((canseemon(mtmp) && (M_AP_TYPE(mtmp) === M_AP_NOTHING
                                      || M_AP_TYPE(mtmp) === M_AP_MONSTER))
                || sensemon(mtmp))
                ++seecount;
        }
    } while (--creatcnt > 0);
    if (seecount) {
        if (seencountRef) seencountRef.count = (seencountRef.count | 0) + seecount;
        if (bag.dknown) {
            makeknown(_BOT_BAG_OF_TRICKS_OTYP);
            update_inventory();
        }
    } else if (!tipping) {
        await pline(!moncount ? nothing_happens : nothing_seems_to_happen);
    }
    return moncount;
}

/* C ref: mkobj.c:2846-2941 hornoplenty(struct obj *horn, boolean tipping,
 * struct obj *targetbox) — create a potion or food item from a horn of
 * plenty.  doapply's own call site (apply.c:4386) always passes
 * `(obj, FALSE, (struct obj *) 0)` — matching bagotricks's header comment
 * above, this port keeps the two extra parameters for a future #loot caller
 * but only the !tipping/!targetbox arm (hold_another_object) is exercised
 * from here.  MEASURED (capture-replay doapply record #12,
 * probe-cov-statecross__gen012-objective-seed1968741 step 3000): this arm was
 * entirely absent, so applying a HORN_OF_PLENTY fell through every otyp check
 * to the default "Sorry, I don't know how to use that." (ECMD_FAIL) instead
 * of ECMD_TIME, and the 4 RNG draws hornoplenty/mkobj/next_ident/mksobj_init
 * make were never consumed at all (rng_result_tape_residual). */
const _HOP_HORN_OF_PLENTY = 252, _HOP_POTION_CLASS = 8, _HOP_FOOD_CLASS = 7;
