/* _can_pray() lived here: an abridged second body of C pray.c:2124 can_pray()
 * that dopray() called while the full faithful port below sat UNWIRED (the
 * dead-port-census UNWIRED row).  The two bodies were statement-identical
 * except that _can_pray() omitted C pray.c:2130-2136 (the is_demon
 * repugnant-to-god early return), C pray.c:2185-2188 (the is_undead rn2(10)
 * branch — the ONLY RNG draw in can_pray), and C pray.c:2193 (the !praying
 * return value).  Unified onto the full body; dopray() now calls can_pray().
 * The only non-C difference between the two was await pline() vs pline():
 * js/display.js:3124 pline() is declared async but contains no await, so its
 * whole effect (_pending_message + _maybe_snapshot_painted_screen) is
 * synchronous and the two spellings are observationally identical. */

/* C ref: pray.c:2123-2194 can_pray(boolean praying) — the single body.  Live:
 * dopray() (C pray.c:2230) calls it.  Synchronous (not async): pline()
 * is fire-and-forget here, matching the established non-awaited pline()
 * convention used elsewhere in this file (e.g. flooreffects_pline_The,
 * pline_mon) for functions that must stay replay-sweep-testable as plain
 * functions.  js/display.js:3124 pline() has no await in its body, so this is
 * observationally identical to awaiting it. */
export function can_pray(praying) {
    const g = game;
    const u = g.u || (g.u = {});
    const onAltar = _on_altar();
    g._p_aligntyp = onAltar ? _a_align(u.ux, u.uy) : (u.ualign?.type ?? 0);
    g._p_trouble = _in_trouble();

    /* C pray.c:2130-2136 — is_demon(gy.youmonst.data) "ok if chaotic or none
     * (Moloch)".  The condition is C's, verbatim and odd: A_CHAOTIC is -1 and
     * therefore != A_NEUTRAL, so the second disjunct swallows the first; the
     * "%s" then prints "lawful" for chaotic too because A_CHAOTIC is truthy.
     * Port the bug (Cardinal Rule 1). */
    if (_is_demon(g.youmonst && g.youmonst.data)
        && (g._p_aligntyp === A_LAWFUL || g._p_aligntyp !== A_NEUTRAL)) {
        if (praying)
            pline('The very idea of praying to a '
                + (g._p_aligntyp ? 'lawful' : 'neutral')
                + ' god is repugnant to you.');
        return false;
    }

    if (praying)
        pline('You begin praying to ' + align_gname(g._p_aligntyp) + '.');

    const record = (u.ualign?.record | 0);
    let alignment;
    if ((u.ualign?.type | 0) && (u.ualign.type | 0) === -g._p_aligntyp)
        alignment = -record;                 /* opposite-alignment altar */
    else if ((u.ualign?.type | 0) !== g._p_aligntyp)
        alignment = Math.trunc(record / 2);  /* different-alignment altar */
    else
        alignment = record;                  /* coaligned */

    const ublesscnt = u.ublesscnt | 0;
    if (g._p_aligntyp === A_NONE) {          /* praying to Moloch */
        g._p_type = -2;
    } else if ((g._p_trouble > 0) ? (ublesscnt > 200)   /* big trouble */
             : (g._p_trouble < 0) ? (ublesscnt > 100)   /* minor difficulty */
               : (ublesscnt > 0)) {                      /* not in trouble */
        g._p_type = 0;                       /* too soon... */
    } else if (_Luck() < 0 || (u.ugangr | 0) || alignment < 0) {
        g._p_type = 1;                       /* too naughty... */
    } else {                                 /* alignment >= 0 */
        if (onAltar && (u.ualign?.type | 0) !== g._p_aligntyp)
            g._p_type = 2;
        else
            g._p_type = 3;
    }

    if (_is_undead(g.youmonst && g.youmonst.data) && !Inhell()
        && (g._p_aligntyp === A_LAWFUL
            || (g._p_aligntyp === A_NEUTRAL && !rn2(10))))
        g._p_type = -1;
    /* Note: when !praying, the random factor for neutrals makes the return
       value a non-deterministic approximation for enlightenment. This case
       should be uncommon enough to live with... */

    return !praying ? (g._p_type === 3 && !Inhell()) : true;
}

/* C ref: cmd.c:6334 paranoid_query(FALSE, prompt) — the non-ParanoidConfirm
 * path: yn_function(prompt, ynchars, 'n', FALSE) → "<prompt> [yn] (n)", reads
 * one key, returns (answer == 'y').  Mirrors potion.js y_n's tty topline flush
 * + cursor placement so the step-boundary capture snapshots the prompt. */
/* Exported under its C name-with-suffix because js/uhitm.js's attack_checks
 * needs the IDENTICAL reader for uhitm.c:319's `paranoid_query(ParanoidHit,
 * "Really attack %s?")`.  A second hand-written copy is how the mirrors in this
 * repo have historically drifted, and this one carries a measured detail a copy
 * would lose: it re-reads on an invalid answer instead of treating it as "no". */
export async function paranoid_query_yn(question) {
    return await _paranoid_query_yn(question);
}
async function _paranoid_query_yn(question) {
    return await paranoid_query(false, question);
}

/* C ref: cmd.c:1094 cmdq_peek(int q) — peek at the top entry of command
 * queue q without removing it.  Returns NULL (in C) if queue is empty.
 * The return value is a pointer to struct _cmd_queue, which the JS port
 * returns as the referenced object or null. */
export function cmdq_peek(q) {
    const g = game;
    // NOTE: game.gc is NOT exclusively owned by this module — sp_lev.js's
    // create_des_coder() (special-level loader, phase3 Is_special path) also
    // creates it (to hold .coder). Guard on the specific field, not the
    // whole object, or a create_des_coder() call before this module's first
    // lazy-init leaves command_queue permanently undefined.
    if (!g.gc) {
        g.gc = {};
    }
    if (!g.gc.command_queue) {
        g.gc.command_queue = [null, null];
    }
    return g.gc.command_queue[q] || null;
}

/* C ref: cmd.c:1080 cmdq_pop(void) — pop the top entry from the command
 * queue.  If gi.in_doagain is true, pop from CQ_REPEAT; otherwise pop from
 * CQ_CANNED.  The selected entry is unlinked from the queue and its next
 * pointer is set to NULL before returning.  Returns NULL (in C) if the queue
 * is empty. */
export function cmdq_pop() {
    const g = game;
    if (!g.gi) {
        g.gi = { in_doagain: false };
    }
    // See cmdq_peek's note: game.gc is shared with sp_lev.js's coder state.
    if (!g.gc) {
        g.gc = {};
    }
    if (!g.gc.command_queue) {
        g.gc.command_queue = [null, null];
    }
    const q = g.gi.in_doagain ? CQ_REPEAT : CQ_CANNED;
    const tmp = g.gc.command_queue[q];
    if (tmp) {
        g.gc.command_queue[q] = tmp.next;
        tmp.next = null;
    }
    return tmp || null;
}

/* C cmd.c:cmdq_add_ec — resolve a function to its first command-table row,
 * then append that row pointer. Row identity is distinct from function
 * identity: call/name share a function but are separate table entries.
 * This port's function lookup uses the C symbol string, as cmd_binds does. */
export function cmdq_add_ec(q, fn) {
    const g = game;
    // See cmdq_peek's note: game.gc is shared with sp_lev.js's coder state.
    if (!g.gc) {
        g.gc = {};
    }
    if (!g.gc.command_queue) {
        g.gc.command_queue = [null, null];
    }
    const tmp = { typ: CMDQ_EXTCMD, ec_entry: ext_func_tab_from_func(fn), next: null };
    let cq = g.gc.command_queue[q];
    // C ref: cmd.c:934 — walk to the tail and append.
    while (cq && cq.next) cq = cq.next;
    if (cq) {
        cq.next = tmp;
    } else {
        g.gc.command_queue[q] = tmp;
    }
}

/* Dispatch table for queued extended-command (CMDQ_EXTCMD) entries.  C's rhack
 * (cmd.c:4317 do_cmdq_extcmd) calls the entry's ef_funct directly; the JS port
 * maps the row's function symbol to the JS command function. Populated lazily at first
 * drain so it can reference functions defined later in this module (dofire,
 * dowield) without a forward-reference hazard. */
let _cmdq_ec_dispatch = null;
function _cmdq_dispatch_for(name) {
    if (!_cmdq_ec_dispatch) {
        _cmdq_ec_dispatch = {
            doswapweapon: _doswapweapon_cmd,
            dofire: dofire,
            dowield: dowield,
            doapply: doapply,
            /* C ref: apply.c:1808 cmdq_add_ec(CQ_CANNED, dorub) — the
             * wield-then-rub re-dispatch. */
            dorub: dorub,
            /* C ref: iactions.c:227 cmdq_add_ec(CQ_CANNED, dothrow) — the
             * item-action menu's 't' row. */
            dothrow: dothrow,
            /* The rest of itemactions_pushkeys (iactions.c:140-268).
             *
             * A NAME MAY ONLY BE ADDED HERE IF ITS COMMAND DRAINS THE QUEUED
             * KEY.  C's getobj() is one function and its first act is to pop a
             * CMDQ_KEY entry (invent.c:1779-1825), so in C every one of these
             * commands picks its object off the queue with no prompt.  This
             * port has no single getobj: only dothrow's hand-rolled loop
             * (cmd.js:2352) and getObjFromGetobj (cmd.js:12277) carry that
             * drain, and dowield / dowear / doeat / dodrop / doapply / doread /
             * dozap / doengrave each read a REAL keystroke with nhgetch().
             * Queueing one of those would leave the invlet sitting in the queue
             * and swallow the session's next key -- a silent input desync that
             * is worse than the no-op it replaces.  So the wiring below is
             * exactly the commands whose object resolution is queue-aware.
             * (See the fleet-feedback note: making getobj the single draining
             * entry point is what unblocks the rest of this table.) */
            doorganize: doorganize,   /* getObjFromGetobj drains the queue */
            do_reqmenu: do_reqmenu,   /* the 'm' prefix; queues no key at all */
            /* Same eat.js command as keyed/named dispatch; its shared getobj
             * consumes the queued selection and honors the menu prefix. */
            doeat: doeat,
            /* C ref: do.c:29 dodrop() → invent.c:1779 getobj("drop", …).  Its
             * copy of getobj's prompt loop now begins with the same drain
             * (cmd.js:7562), so iactions.c:173's queued invlet is consumed with
             * no prompt.  No m-prefix on this row: C queues dodrop alone. */
            dodrop: dodrop,
            /* C ref: iactions.c:254-256 — IA_WEAR_OBJ queues dowear and
             * the selected inventory letter.  The shared getobj drain
             * consumes that queued letter without reading nhgetch. */
            dowear: dowear, /* checks hands/slots before its queued getobj */
            docallcmd: docallcmd,
        };
    }
    return _cmdq_ec_dispatch[name] || null;
}

/* C ref: hack.c:914 may_passwall(coordxy x, coordxy y) — returns true iff
 * the location at (x, y) is passable through (not a stone wall or a
 * non-passable wall). A stone wall is never passable. A wall is passable
 * only if it is NOT marked with the W_NONPASSWALL flag.  In C, returns
 * (boolean) which is a typedef for unsigned char, so we return a true boolean. */
export function may_passwall(x, y) {
    const g = game;
    const lev = g.level.at(x, y);
    return !(IS_STWALL(lev.typ) && (lev.wall_info & W_NONPASSWALL));
}

/* C ref: hack.c:921 bad_rock(mdat,x,y) — returns true if location is obstructed
 * by a boulder that can't be moved (Sokoban) or by terrain impassable to mdat. */
export function bad_rock(mdat, x, y) {
    // Sokoban check — C macro Sokoban → svl.level.flags.sokoban_rules
    const sokoban = !!(game.level?.flags?.sokoban_rules ?? game.sokoban);
    if (sokoban && sobj_at(BOULDER_OTYP, x, y)) return true;

    const loc = game.level?.at(x, y);
    const typ = loc ? (loc.typ | 0) : STONE;
    if (!IS_OBSTRUCTED(typ)) return false;

    const mf1 = mdat ? (mdat.mflags1 | 0) : 0;
    const tunnels_val = (mf1 & 0x20) !== 0;   // M1_TUNNEL
    const needspick_val = (mf1 & 0x40) !== 0;  // M1_NEEDPICK
    const passes_walls_val = (mf1 & 0x08) !== 0; // M1_WALLWALK

    if ((!tunnels_val || needspick_val || !may_dig(x, y))
        && !(passes_walls_val && may_passwall(x, y))) {
        return true;
    }
    return false;
}

/* C ref: hack.c:935 cant_squeeze_thru(mon) — check whether a monster
 * (who might be the hero) can fit through a tight diagonal, and if not
 * return the reason: 1: can't fit, 2: possessions won't fit, 3: sokoban.
 * returns 0 if we can squeeze through. */
export function cant_squeeze_thru(mon) {
    const ptr = mon.data;
    const is_hero = (mon === game.youmonst);
    const mf1 = (ptr.mflags1 | 0);
    const mlet = (ptr.mlet | 0);
    const msize = (ptr.msize | 0);
    const pmidx = (ptr.pmidx | 0);

    if (is_hero ? _uprop_active('PASSES_WALLS') : ((mf1 & 0x08) !== 0))
        return 0;

    /* too big? */
    /* C mondata.h:12 bigmonst(ptr) = (ptr->msize >= MZ_LARGE); monflag.h:181
     * MZ_LARGE = 3.  (This used to test >= 4, i.e. MZ_HUGE, letting every
     * MZ_LARGE monster squeeze through a tight diagonal that C refuses.) */
    const big = (msize >= 3);                             /* MZ_LARGE */
    const amorphous   = (mf1 & 0x04) !== 0;                /* M1_AMORPHOUS */
    const whirly      = (mlet === S_VORTEX || pmidx === 158); /* PM_AIR_ELEMENTAL */
    const noncorporeal = (mlet === S_GHOST);
    const slithy      = (mf1 & 0x00080000) !== 0;          /* M1_SLITHY */
    if (big && !(amorphous || whirly || noncorporeal || slithy || can_fog(mon)))
        return 1;

    /* lugging too much junk? */
    let amt;
    if (is_hero) {
        amt = inv_weight() + weight_cap();
    } else {
        /* Inline curr_mon_load — use owt to avoid globby access */
        amt = 0;
        for (let obj = mon.minvent; obj; obj = obj.nobj) {
            amt += (obj.owt | 0);
        }
    }
    if (amt > WT_TOOMUCH_DIAGONAL)
        return 2;

    /* Sokoban restriction applies to hero only */
    const sokoban = !!(game.level?.flags?.sokoban_rules ?? game.sokoban);
    if (is_hero && sokoban)
        return 3;

    return 0;
}

/* C hack.c:2421 u_maybe_impaired() — return (Stunned || (Confusion && !rn2(5))).
 * Stunned/Confusion are HStun/HConfusion = u.uprops[STUNNED/CONFUSION].intrinsic
 * (intrinsic ONLY, per youprop.h:80-84). uprops seeded from the sensing
 * side-channel (wsv Phase-2d: STUNNED/CONFUSION added to snapshot_sensing).
 * The rn2(5) is consumed ONLY when not-Stunned AND Confusion (C short-circuit).
 *
 * u.uprops is keyed by the NUMERIC prop.h index (STUNNED = 13, CONFUSION = 14
 * in js/const.js) — `up.STUNNED` / `up.CONFUSION` are STRING keys that nothing
 * in js/ ever writes, so both reads were permanently undefined and this
 * function was a constant FALSE that never drew.  Dormant while nothing could
 * confuse the hero; wrong the moment make_confused started writing the real
 * word (seed0002 step 238 is exactly one rn2(5) @ u_maybe_impaired(hack.c:2420)
 * ahead of where JS starts drawing). */
export function u_maybe_impaired() {
    const up = game.u?.uprops;
    const Stunned = (up?.[STUNNED]?.intrinsic) | 0;
    const Confusion = (up?.[CONFUSION]?.intrinsic) | 0;
    return !!(Stunned || (Confusion && !rn2(5)));
}

/* C hack.c:2424-2440 impaired_movement(coordxy *x, coordxy *y) — the confused /
 * stunned hero's movement direction is replaced with a random legal one:
 *     if (u_maybe_impaired()) {
 *         int tries = 0;
 *         do {
 *             if (tries++ > 50) { nomul(0); return TRUE; }
 *             confdir(TRUE);
 *             *x = u.ux + u.dx;  *y = u.uy + u.dy;
 *         } while (!isok(*x, *y) || bad_rock(gy.youmonst.data, *x, *y));
 *     }
 *     return FALSE;
 * Called from domove_core (hack.c:2747) between slippery_ice_fumbling() and
 * water_turbulence(), i.e. BEFORE anything else in the move spends RNG — which
 * is why its rn2(5) is index 0 of seed0002's step 238.
 * Returns {blocked, dx, dy}: this port's domove_core is passed (dx, dy) rather
 * than reading u.dx/u.dy, so the new direction is handed back rather than left
 * in u.dx/u.dy alone (both are written, as C does, for callees that read them). */
function impaired_movement(dx, dy) {
    const u = game.u;
    if (!u_maybe_impaired())
        return { blocked: false, dx, dy };
    let tries = 0;
    let x, y;
    do {
        if (tries++ > 50) {
            nomul(0);
            return { blocked: true, dx: u.dx | 0, dy: u.dy | 0 };
        }
        confdir(true);
        x = u.ux + u.dx;
        y = u.uy + u.dy;
    } while (!isok(x, y) || bad_rock(game.youmonst?.data, x, y));
    return { blocked: false, dx: u.dx | 0, dy: u.dy | 0 };
}

/* C hack.c:2400 slippery_ice_fumbling().  Ice does not move the hero on the
 * current turn; it arms the FROMOUTSIDE fumbling bit so slip_or_trip() runs on
 * the next turn.  Keep the draw before impaired_movement(), exactly where C
 * places it in domove_core. */
function slippery_ice_fumbling() {
    const u = game.u || {};
    /* C's HFumbling slot is materialized by the timeout machinery only after
     * this helper first runs.  Returning when the slot is absent drops the
     * eligible-ice rn2() and shifts the entire monster phase (gen406 turn
     * 178 is the measured witness). */
    if (!u.uprops)
        u.uprops = {};
    const p = u.uprops[_PROPIDS.FUMBLING]
        || (u.uprops[_PROPIDS.FUMBLING] = { intrinsic: 0, extrinsic: 0, blocked: 0 });
    const onIce = !_Levitation() && _is_ice(u.ux | 0, u.uy | 0);
    const steed = u.usteed;
    const data = steed?.data || _hero_youmonst().data;
    const coldRes = steed
        ? !!((data?.mresists | 0) & 0x02)
        : _Cold_resistance();
    const flyer = steed
        ? !!((data?.mflags1 | 0) & 0x01)
        : _Flying();
    const floater = _st_is_floater(data);
    const clinger = _pe_is_clinger(data);
    const whirly = (data?.mlet | 0) === 22;
    const snowBoots = !steed && ((u.uarmf?.otyp | 0) === 172);
    if (onIce && !snowBoots && !flyer && !floater && !clinger && !whirly) {
        /* hack.c:2407: Cold_resistance changes the denominator, but does not
         * suppress the roll. */
        if (!rn2(coldRes ? 3 : 2)) {
            p.intrinsic = ((p.intrinsic | 0) & ~TIMEOUT) | FROMOUTSIDE | 1;
        }
    } else if ((p.intrinsic | 0) & FROMOUTSIDE) {
        p.intrinsic = (p.intrinsic | 0) & ~FROMOUTSIDE;
    }
}

/* C hack.c:2648-2710 escape_from_sticky_mon().  A hero who is held by a
 * monster cannot simply walk away: this check runs after the movement
 * direction has been resolved and before m_at()/attack dispatch.  The
 * rn2(8)/rn2(40) choice is therefore part of the movement stream, even when
 * the holder remains in place. */
export async function escape_from_sticky_mon(x, y) {
    const u = game.u || {};
    const holder = u.ustuck;
    if (!holder || ((x | 0) === (holder.mx | 0) && (y | 0) === (holder.my | 0)))
        return false;

    /* C m_next2u(): a holder that is no longer adjacent has fled, teleported,
     * or otherwise released the hero. */
    const adjacent = Math.max(Math.abs((holder.mx | 0) - (u.ux | 0)),
                              Math.abs((holder.my | 0) - (u.uy | 0))) <= 1;
    if (!adjacent) {
        set_ustuck(null);
        return false;
    }

    /* When polymorphed into a sticking form, u.ustuck points at the monster
     * held by the hero rather than the monster holding the hero. */
    if (sticks(game.youmonst?.data)) {
        set_ustuck(null);
        await pline(`You release ${y_monnam(holder)}.`);
        return false;
    }

    /* A tame, non-conflicting holder is always released.  The random check is
     * skipped in that case, matching C's switch fall-through. */
    const asleep = !(holder.mcanmove | 0);
    const roll = holder.mcanmove ? rn2(40) : rn2(8);
    if (roll === 3 && asleep) {
        holder.mfrozen = 1;
        holder.msleeping = 0;
    }
    const escape = roll <= 2 || (!((game.u?.uprops?.[CONFLICT]?.intrinsic | 0)
                                   || (game.u?.uprops?.[CONFLICT]?.extrinsic | 0))
                                && !(holder.mconf | 0) && (holder.mtame | 0));
    if (escape) {
        set_ustuck(null);
        await pline(`You pull free from ${y_monnam(holder)}.`);
        return false;
    }
    await pline(`You cannot escape from ${y_monnam(holder)}!`);
    nomul(0);
    return true;
}

/* C ref: invent.c:1612 g_at() — find the first COIN_CLASS object at (x, y).
 * Returns the object if found, null otherwise. Walks the per-tile nexthere chain
 * looking for the first coin. */
export function g_at(x, y) {
    const g = game;
    const xi = x | 0;
    const yi = y | 0;
    let obj = (g.level?.levelObjects?.[xi]?.[yi]) ?? null;

    while (obj) {
        if ((obj.oclass | 0) === OCLASS_COIN)
            return obj;
        obj = obj.nexthere ?? null;
    }
    return null;
}

/* C wield.c:set_twoweap — a changed weapon mode can dirty the status line. */
export function set_twoweap(on_off) {
    const u = game.u;
    if (!!on_off !== !!u.twoweap) {
        u.twoweap = on_off;
        if (game.flags.weaponstatus)
            game.disp.botl = true;
    }
}

export function set_uinwater(in_out) {
    const u = game.u;
    u.uinwater = in_out ? 1 : 0;
}

/* C ref: hack.c:1695 u_rooted() — check if rooted (mmove == 0).
 * If rooted, display message and call nomul(0). Returns true if rooted. */
export function u_rooted() {
    const g = game;
    const ym = _hero_youmonst();
    if (!ym.data.mmove) {
        You("are rooted %s.",
            _Levitation() || Is_airlevel(g.u.uz) || Is_waterlevel(g.u.uz)
                ? "in place"
                : "to the ground");
        nomul(0);
        return true;
    }
    return false;
}

/* C wield.c:setuswapwep — setworn owns the inventory refresh. */
export async function setuswapwep(obj) {
    await setworn(obj, W_SWAPWEP_C);
}

/* C wield.c:setuqwep — no additional inventory refresh. */
export async function setuqwep(obj) {
    await setworn(obj, W_QUIVER_C);
}

/* boulder_hits_pool local stubs — helpers reached only from the pool/lava
 * fill/splash arm (do.c:57 else-if) that are not yet ported.  Following the
 * pooleffects_* convention used elsewhere in this file: keep the C control
 * flow faithful, throw on the unported call so a live path surfaces it.
 * (In the captured corpus every record exits via is_pool_or_lava()==FALSE,
 * so this arm is not exercised.) */
const BOULDER_OTYP = 475; /* objects.h BOULDER */
const se_splash = 0, se_sizzling = 0; /* sound.h se_* enum — unported */
export function bhp_is_lava(x, y) { return is_lava(x, y); }
export function bhp_waterbody_name(x, y) { return waterbody_name(x, y); }
export function bhp_recalc_block_point(x, y) { return recalc_block_point(x, y); }
export function bhp_m_in_air(mtmp) { return m_in_air(mtmp); }
export async function bhp_mondied(mtmp) { return await mondied(mtmp); }
export async function bhp_delfloortrap(ttmp) { return await delfloortrap(ttmp); }
/* C do.c:97-112 bury_objs(x,y).  This helper is synchronous in C and in the
 * JS object model; bury_an_obj() returns the next per-tile object after it
 * extracts or deallocates the current one. */
export async function bhp_bury_objs(x, y) {
    let otmp = game.level?.levelObjects?.[x]?.[y] || null;
    while (otmp) {
        otmp = (await bury_an_obj(otmp, null));
    }
    del_engr_at(x, y);
    newsym(x, y);
    maybe_unhide_at(x, y);
}
export function bhp_y_monnam(mtmp) { return y_monnam(mtmp); }
export function bhp_upstart(s) { return upstart(s); }
export function bhp_the(s) { return the(s); }
export function bhp_xname(obj) { return _fw_xname(obj); }
/* Audio-only in the C build; no replay-visible state or RNG. */
export function bhp_Soundeffect() { return undefined; }
/* C ref: do.c:122 You_hear("a%s splash.", lava ? " sizzling" : "") — was
 * `throw new Error('not yet ported: You_hear')` on boil_away/water-fall's live
 * path.  The call site at :22226 sits behind C's own `!Deaf` test (do.c:119),
 * and You_hear re-tests it exactly as C does. */
export function bhp_You_hear(fmt, ...args) { return You_hear(fmt, ...args); }
export function bhp_wake_nearto(x, y, distance) { return wake_nearto(x, y, distance); }
export function bhp_hliquid(pref) { return hliquid(pref); }
/* C timeout.c:447-452 burn_away_slime().  make_slimed() updates the property
 * before its optional message await, and this boulder/pool caller is
 * synchronous; no RNG or state ordering is lost by starting that message. */
export function bhp_burn_away_slime() {
    const p = game.u?.uprops?.[SLIMED];
    if ((p?.intrinsic | 0) || (p?.extrinsic | 0))
        void make_slimed(0, 'The slime that covers you is burned away!');
}
export async function bhp_losehp(n, knam, kfmt) { return await losehp(n, knam, kfmt); }
export async function bhp_useupf(obj, numused) { return await useupf(obj, numused); }
export async function bhp_obfree(obj, merge) { return await obfree(obj, merge); }
export async function bhp_There(msg, ...args) { return await _There(msg, ...args); }
export function bhp_Fire_resistance() { return _Fire_resistance(); }
export function bhp_Maybe_Half_Phys(dmg) { return flooreffects_Maybe_Half_Phys(dmg); }

/* C ref: do.c:49 boulder_hits_pool(otmp, rx, ry, pushing) — a boulder falls
 * (or is pushed) into a pool/water/lava at (rx,ry); may fill it in, splash,
 * or sink.  Returns TRUE if the boulder was consumed by the pool. */
export async function boulder_hits_pool(otmp, rx, ry, pushing) {
    if (!otmp || otmp.otyp !== BOULDER_OTYP) {
        impossible("Not a boulder?");
    } else if (is_pool_or_lava(rx, ry)) {
        const lava = bhp_is_lava(rx, ry);
        let fills_up;
        const what = bhp_waterbody_name(rx, ry);
        const ltyp = _levlAt(rx, ry).typ;
        const chance = rn2(10); /* water: 90%; lava: 10% */
        let mtmp;

        /* chance for boulder to fill pool:  Plane of Water==0%,
           lava 10%, wall of water==50%, other water==90% */
        fills_up = Is_waterlevel(game.u.uz) ? false
                   : IS_WATERWALL(ltyp) ? (chance < 5)
                     : lava ? (chance === 0) : (chance !== 0);

        if (fills_up) {
            const ttmp = t_at(rx, ry);

            if (ltyp === DRAWBRIDGE_UP) {
                const loc = _levlAt(rx, ry);
                loc.drawbridgemask &= ~DB_UNDER; /* clear lava */
                loc.drawbridgemask |= DB_FLOOR;
            } else {
                const loc = _levlAt(rx, ry);
                loc.typ = ROOM;
                loc.flags = 0;
                bhp_recalc_block_point(rx, ry);
            }
            /* 3.7: normally DEADMONSTER() is used when traversing the fmon
               list; however a drowned giant dropping a boulder that fills the
               pool can be dead here — killing it again would yield an
               impossible "dmonsfree" mismatch. */
            if ((mtmp = m_at(rx, ry)) && !DEADMONSTER(mtmp)
                && !bhp_m_in_air(mtmp))
                await bhp_mondied(mtmp);

            if (ttmp)
                await bhp_delfloortrap(ttmp);
            await bhp_bury_objs(rx, ry);

            newsym(rx, ry);
            if (pushing) {
                let whobuf = "you";
                if (game.u.usteed)
                    whobuf = bhp_y_monnam(game.u.usteed);
                pline("%s %s %s into the %s.", bhp_upstart(whobuf),
                      vtense(whobuf, "push"), bhp_the(bhp_xname(otmp)), what);
                const Blind = _Blind_cmd();
                if (game.flags.verbose && !Blind)
                    pline("Now you can cross it!");
                /* no splashing in this case */
            }
        }
        if (!fills_up || !pushing) { /* splashing occurs */
            const Blind = _Blind_cmd();
            if (!game.u.uinwater) {
                if (pushing ? !Blind : cansee(rx, ry)) {
                    const splash = nh_sprintf("There is a large splash as %s %s the %s.",
                          [bhp_the(bhp_xname(otmp)), fills_up ? "fills" : "falls into", what]);
                    await pline_with_more(splash, game.u?.uac ?? 0);
                } else if (!_hero_Deaf()) {
                    if (lava) {
                        bhp_Soundeffect(se_sizzling, 100);
                    } else {
                        bhp_Soundeffect(se_splash, 100);
                    }
                    await bhp_You_hear("a%s splash.", lava ? " sizzling" : "");
                }
                bhp_wake_nearto(rx, ry, 40);
            }

            const u = game.u;
            const distu0 = (rx - u.ux) * (rx - u.ux) + (ry - u.uy) * (ry - u.uy);
            const next2u0 = Math.abs(rx - u.ux) <= 1 && Math.abs(ry - u.uy) <= 1;
            if (fills_up && u.uinwater && distu0 === 0) {
                set_uinwater(0); /* u.uinwater = 0 */
                docrt();
                game.vision_full_recalc = 1;
                You("find yourself on dry land again!");
            } else if (lava && next2u0) {
                let dmg;

                You("are hit by molten %s%c",
                    bhp_hliquid("lava"), bhp_Fire_resistance() ? '.' : '!');
                bhp_burn_away_slime();
                dmg = d((bhp_Fire_resistance() ? 1 : 3), 6);
                await bhp_losehp(bhp_Maybe_Half_Phys(dmg), /* lava damage */
                       "molten lava", KILLED_BY);
            } else if (!fills_up && game.flags.verbose
                       && (pushing ? !Blind : cansee(rx, ry))) {
                await pline("It sinks without a trace!");
            }
        }

        /* boulder is now gone */
        if (pushing)
            await bhp_useupf(otmp, otmp.quan);
        else
            await bhp_obfree(otmp, null);
        return true;
    }
    return false;
}

/* C ref: insight.c:2516-2522 achieve_rank(int rank) — compute the achievement
 * index for a given rank (1..8), optionally negating based on female hero.
 * Return type is schar: `schar achidx = (schar) ((rank - 1) + ACH_RNK1);` —
 * narrow to signed 8-bit BEFORE the female negation (C casts before the `if`,
 * not after). (x << 24) >> 24 is JS's signed-32 idiom for a schar truncation. */
export function achieve_rank(rank) {
    let achidx = (((rank - 1) + ACH_RNK1) << 24) >> 24;
    if (game.flags.female) {
        achidx = -achidx;
    }
    return achidx;
}

/* C ref: pray.c:2199 dopray() — the #pray command.  Sets the praying
 * occupation and returns ECMD_TIME so the moveloop runs the prayer-out turns. */
export async function dopray() {
    const g = game;
    const u = g.u || (g.u = {});

    /* C ref: pray.c:2208 — ParanoidPray (default-on, options.c:7178) gates the
     * "Are you sure you want to pray?" confirmation.  be_paranoid is
     * ParanoidConfirm (default OFF) → a simple y_n with "[yn] (n)".  No corpus
     * session sets paranoid_confirmation:pray-off, so ParanoidPray is on. */
    /* options.c seeds this compound option before reading the rc file.  Older
     * saved/test games can lack the JS field, so absence means the C default;
     * an explicit zero still disables every confirmation. */
    const bits = (g.flags?.paranoia_bits
                  ?? PARANOID_CONFIRMATION_DEFAULT_BITS) | 0;
    if (bits & PARANOID_PRAY) {
        const ok = await paranoid_query(!!(bits & PARANOID_CONFIRM),
                                        'Are you sure you want to pray?');
        if (!ok) {                           /* declined → ECMD_OK, no turn */
            g.context.move = 0;
            return ECMD_OK; // C ref: pray.c:2218 `if (!ok) return ECMD_OK;`
        }
    }

    /* C pray.c:2224-2227 —
     *     if (!u.uconduct.gnostic++)
     *         livelog_printf(LL_CONDUCT, "rejected atheism with a prayer");
     * POST-increment: the test is on the value BEFORE the bump, so the log
     * fires on the FIRST prayer only.  The livelog half was dropped as "no
     * screen effect", which was true only while livelog_printf was a no-op
     * stub: gg.gamelog IS the '#chronicle' window (insight.c:2571), and
     * seed0106 step 188 shows C's entry "    2: rejected atheism with a
     * prayer" that we were missing.  RNG-free. */
    u.uconduct = u.uconduct || {};
    if (!((u.uconduct.gnostic | 0))) {
        u.uconduct.gnostic = 1;
        livelog_printf(LL_CONDUCT, "rejected atheism with a prayer");
    } else {
        u.uconduct.gnostic = (u.uconduct.gnostic | 0) + 1;
    }

    /* C ref: pray.c:2230 — `if (!can_pray(TRUE)) return ECMD_OK;`. */
    if (!can_pray(true)) {                   /* prints "You begin praying…" */
        g.context.move = 0;                  /* ECMD_OK — no turn */
        return ECMD_OK; // C ref: pray.c:2231 `if (!can_pray(TRUE)) return ECMD_OK;`
    }

    /* C ref: pray.c:2233-2258 — wizard force-success branch.  In wizard
     * (playmode:debug) mode with gp.p_type >= 0, the game offers "Force the gods
     * to be pleased?".  seed0116 (Wizard, debug) reaches it: the "begin praying"
     * topline is flushed (→ --More--) and the y_n prompt is shown.  On 'y' the
     * god is forced pleased — ublesscnt/uluck/ualign.record/ugangr are reset and
     * p_type is forced to 3 (the coaligned-reward outcome), which fires the
     * shimmering-light invulnerability below and the pleased() prayer_done path. */
    if ((g.flags && g.flags.debug) && (g._p_type | 0) >= 0) {
        /* C ref: win/tty/topl.c — can_pray() just printed "You begin praying to
         * %s." to the topline but the player has not acked it (no input since).
         * The wizard y_n() prompt that follows therefore more()s the unacked
         * topline first (a forced, non-width more() — the hero is stationary so
         * the live map is correct).  Page it, consuming the recorded dismiss key,
         * before the prompt overwrites the topline. */
        if (g._pending_message)
            await force_more(g._pending_message);
        /* pray.c:2244/2247 — ParanoidPray uses YN(), else y_n(); both render
         * "<prompt> [yn] (n)" and default to 'n'.  Reuse the paranoid y_n helper. */
        const force = await _paranoid_query_yn('Force the gods to be pleased?');
        if (force) {
            u.ublesscnt = 0;                 /* pray.c:2250 */
            if ((u.uluck | 0) < 0) u.uluck = 0; /* pray.c:2251-2252 */
            u.ualign = u.ualign || {};
            if ((u.ualign.record | 0) <= 0) u.ualign.record = 1; /* pray.c:2253-2254 */
            u.ugangr = 0;                    /* pray.c:2255 */
            if ((g._p_type | 0) < 2) g._p_type = 3; /* pray.c:2256-2257 */
        }
    }

    nomul(-3);                               /* hack.c:4068 — praying occupation */
    g.multi_reason = 'praying';              /* pray.c:2261 */
    g.nomovemsg = 'You finish your prayer.'; /* pray.c:2262 */
    g.afternmv = 'prayer_done';              /* pray.c:2263 */

    if (g._p_type === 3 && !Inhell()) {       /* C pray.c:2265 */
        /* C ref: pray.c:2265-2270 — coaligned, true-to-god: "if you've been true
         * to your god you can't die while you pray."  Print the shimmering-light
         * message (unless Blind) and set the invulnerability flag, which makes
         * gethungry() (eat.c:3167) return early for the prayer-countdown turns. */
        if (!_uprop_active('BLINDED'))
            await pline('You are surrounded by a shimmering light.');
        u.uinvulnerable = true;
    }
    /* ECMD_TIME — doextcmd() zeroed context.move before dispatch; restore it to
     * 1 so the faithful moveloop runs the praying turns and then fires
     * unmul→prayer_done. */
    g.context.move = 1;
    return ECMD_TIME; // C ref: pray.c:2272 `return ECMD_TIME;`
}

/* local helpers for doturn — not exported from their source modules */
const PM_CLERIC = 6;  /* role index for Priest/Priestess */
const PM_KNIGHT = 4;  /* role index for Knight */
const _SPE_TURN_UNDEAD = 398; /* spell ID for turn undead */
const _M2_DEMON = 0x00000100;
const _M2_UNDEAD = 0x00000002;

function _Role_if(pm) {
    /* pm is a role index (PM_CLERIC=6, PM_KNIGHT=4).  C: Role_if checks
       urole.mnum == pm - LOW_PM; LOW_PM is 0 in this port. */
    return ((game.flags?.initrole ?? -1) | 0) === pm;
}

function _is_demon(ptr) {
    return ptr && ((ptr.mflags2 | 0) & _M2_DEMON) !== 0;
}

function _is_undead(ptr) {
    return ptr && ((ptr.mflags2 | 0) & _M2_UNDEAD) !== 0;
}

function _is_vampshifter(mon) {
    return mon && (mon.cham === PM_VAMPIRE || mon.cham === PM_VAMPIRE_LORD
        || mon.cham === PM_VLAD_THE_IMPALER);
}

function iter_mons(callback) {
    return iter_mons_real(callback);
}

/* C ref: pline.c:514 livelog_printf — was a no-op stub here (and another copy
 * in js/exper.js), so every chronicle event this file logs was dropped and
 * '#chronicle' showed only the game-start line.  The real one lives next to
 * pline() in js/display.js, as it does in C's pline.c, and is imported above. */

/* spell.c:1385 — use the canonical dispatcher in spell.js.  This local name
 * remains for the turn-undead call below, while avoiding a second body that
 * could drift from ordinary spell casting. */
async function spelleffects(spell, ...args) {
    return await spelleffects_real(spell, ...args);
}

function maybe_turn_mon_iter() {
    /* stub — iter_mons callback, not called while iter_mons is stubbed */
}

/* C ref: pray.c:2414 doturn() — Knights & Priest(esse)s only #turn command */
export async function doturn() {
    const g = game;
    const u = g.u || (g.u = {});
    const youmonst = g.youmonst;
    const ymData = youmonst && youmonst.data;

    /* Knights & Priest(esse)s only please */
    if (!_Role_if(PM_CLERIC) && !_Role_if(PM_KNIGHT)) {
        if (known_spell(_SPE_TURN_UNDEAD))
            return await spelleffects(_SPE_TURN_UNDEAD, false, false);
        await You("don't know how to turn undead!");
        return ECMD_OK;
    }

    u.uconduct = u.uconduct || {};
    /* C pray.c:2425-2427 `if (!u.uconduct.gnostic++) livelog_printf(...)` is a
     * POST-increment, so the guard tests the PRE-bump value.  This read the
     * POST-bump value, which is >= 1 on every path and therefore never true --
     * the entry could not fire even once.  The flag was also literally 0 rather
     * than LL_CONDUCT (const.js:749 = 0x20), which show_gamelog's `final`
     * filter tests against LL_majors. */
    if (!((u.uconduct.gnostic | 0))) {
        u.uconduct.gnostic = 1;
        livelog_printf(LL_CONDUCT, "rejected atheism by turning undead");
    } else {
        u.uconduct.gnostic = (u.uconduct.gnostic | 0) + 1;
    }

    const Gname = halu_gname(u.ualign?.type | 0);

    if (!can_chant(youmonst)) {
        await You("are %s upon %s to turn aside evilness.",
            _uprop_active('STRANGLED') ? "not able to call" : "incapable of calling", Gname);
        g.context.move = (u.uconduct.gnostic === 1) ? 1 : 0;
        return (u.uconduct.gnostic === 1) ? ECMD_TIME : ECMD_OK;
    }

    if (((u.ualign?.type | 0) !== A_CHAOTIC
         && (_is_demon(ymData) || _is_undead(ymData) || _is_vampshifter(youmonst)))
        || (u.ugangr | 0) > 6) {
        await pline("For some reason, %s seems to ignore you.", Gname);
        aggravate();
        exercise(A_WIS, false);
        g.context.move = 1;
        return ECMD_TIME;
    }

    if ((u.uz?.dnum | 0) === GEHENNOM) {
        await pline(_plineVFmt("Since you are in Gehennom, %s %s help you.",
            [Gname, Gname === 'Moloch' ? "won't" : "can't"]));
        aggravate();
        g.context.move = 1;
        return ECMD_TIME;
    }

    await pline(_plineVFmt("Calling upon %s, you chant an arcane formula.", [Gname]));
    exercise(A_WIS, true);

    /* note: does not perform unturn_dead() on victims' inventories */
    g.turn_undead_range = BOLT_LIM + Math.trunc((u.ulevel | 0) / 5); /* 8 to 14 */
    g.turn_undead_range *= g.turn_undead_range;
    g.turn_undead_msg_cnt = 0;

    iter_mons(maybe_turn_mon_iter);

    nomul(-(5 - Math.trunc(((u.ulevel | 0) - 1) / 6))); /* -5 .. -1 */
    g.multi_reason = "trying to turn the monsters";
    g.nomovemsg = "You can move again.";
    g.context.move = 1;
    return ECMD_TIME;
}

/* C ref: pray.c:1435 gods_upset(g_align) — ugangr bookkeeping then angrygods. */
async function _gods_upset(gAlign) {
    const u = game.u || (game.u = {});
    if (gAlign === (u.ualign?.type | 0)) u.ugangr = (u.ugangr | 0) + 1;
    else if (u.ugangr | 0) u.ugangr = (u.ugangr | 0) - 1;
    await _angrygods(gAlign);
}

/* C ref: pray.c:704 angrygods(resp_god) — the god's displeasure response.
 * Cases 0-5 are ported; case 6 (unless Punished), cases 7-8, and default still
 * require the source helpers summon_minion/god_zaps_you/punish. */
async function _angrygods(respGod) {
    const u = game.u || (game.u = {});
    /* Inhell → resp_god = A_NONE (not reachable in the corpus). */
    u.ublessed = 0;                          /* lose divine protection */

    let maxanger;
    const record = (u.ualign?.record | 0);
    const Luck = _Luck();
    if (respGod !== (u.ualign?.type | 0)) {
        maxanger = Math.trunc(record / 2) + (Luck > 0 ? Math.trunc(-Luck / 3) : -Luck);
    } else {
        maxanger = 3 * (u.ugangr | 0)
            + ((Luck > 0 || record >= STRIDENT_PRAY) ? Math.trunc(-Luck / 3) : -Luck);
    }
    if (maxanger < 1) maxanger = 1;
    else if (maxanger > 15) maxanger = 15;

    const roll = rn2(maxanger);              /* pray.c:725 */
    switch (roll) {
        case 0:
        case 1:
            /* pray.c:729 — Hallucination changes the deity's adjective. */
            await pline(`You feel that ${_align_gname(respGod)} is ${_cmd_Hallucination() ? 'bummed' : 'displeased'}.`);
            break;
        case 2:
        case 3:
            /* pray.c:731-742.  godvoice draws the rn2(4) that seed0106's
             * scored run was missing entirely (leaf 2632). */
            await godvoice(respGod, null);
            await pline(`"Thou ${(_ugod_is_angry() && respGod === (u.ualign?.type | 0))
                            ? "hast strayed from the path"
                            : "art arrogant"}, ${
                        (_hero_youmonst()?.data?.mlet | 0) === S_HUMAN
                            ? "mortal" : "creature"}."`);
            SetVoice(null, 0, 80, 0 /* voice_deity */);
            await verbalize("Thou must relearn thy lessons!");
            /* C passes FALSE (== 0), not a JS boolean: attrib.c's msgflg is
             * compared with `== 0` as well as `<= 0`, and `false === 0` is
             * false in JS. */
            adjattrib(A_WIS, -1, 0);
            await losexp(null);
            break;
        case 4:
        case 5:
            /* C pray.c:744-760 — gods_angry(), then the black glow and
             * conditional attrcurse/rndcurse sequence. */
            await godvoice(respGod, "Thou hast angered me.");
            if (!_hero_Blind() && !_uprop_active('ANTIMAGIC')) {
                const glow = hcolor(NH_BLACK);
                const article = upstart(_an(glow));
                await pline(`${article} glow surrounds you.`);
            }
            if (rn2(2) || !(await attrcurse()))
                await rndcurse();
            break;
        default:
            /* case 6 (unless Punished) and cases 7-8/default still require
             * their source helpers; keep the explicit sentinel for those. */
            g_uncomputable_pray(`angrygods case ${roll}/${maxanger}`);
            break;
    }
    /* pray.c:780 — reset pray timer even outside prayer.  rnz(300). */
    const newUblesscnt = rnz(300);
    if (newUblesscnt > (u.ublesscnt | 0)) u.ublesscnt = newUblesscnt;
}

