/* C ref: sit.c:396 dosit() — the #sit command. */
export async function dosit() {
    const g = game;
    const u = g.u || (g.u = {});
    /* C objects.h FOOD("cream pie") / ARMOR("water walking boots").  Resolved
     * with tools/c-const-oracle.mjs against the 5.0 headers and cross-checked
     * BY NAME in js/oc_name_data.js (MEMORY: otyp ids are not greppable —
     * objects.h is an X-macro file).  The literals these replace were 266,
     * which oc_name_data.js names "egg", and 305, which it names
     * "invisibility": the cream-pie arm tested for an egg, and the boots check
     * compared a boot slot against a potion.  287 is the value
     * js/m_initweap.js:144, js/mhitm.js:3513, js/cmd.js:25046 and
     * js/mhitu.js:1690 already agree on.
     * NOTE js/cmd.js:27493 WATER_WALKING_BOOTS_SMD = 87 is wrong the same way
     * (oc_name_data.js[87] is "sling"); it is outside this block and is
     * reported, not changed. */
    const CREAM_PIE_SIT = 287, WATER_WALKING_BOOTS_SIT = 167;
    const sit_message = "sit on the %s.";

    const trap = t_at(u.ux | 0, u.uy | 0);
    const loc = _levlAt(u.ux | 0, u.uy | 0);
    const typ = loc ? (loc.typ | 0) : 0;

    if (u.usteed) {
        await You("are already sitting on %s.", mon_nam(u.usteed));
        g.context.move = 0;
        return ECMD_OK;
    }

    if (u.uundetected && (u.umonnum | 0) !== 78) {
        u.uundetected = 0;
    }

    if (!_can_reach_floor(false)) {
        if (u.uswallow) {
            await _There("are no seats in here!");
        } else if (_Levitation()) {
            await You("tumble in place.");
        } else {
            await You("are sitting on air.");
        }
        g.context.move = 0;
        return ECMD_OK;
    } else if (u.ustuck && !_sticks()) {
        if (_humanoid(u.ustuck?.data)) {
            await pline("%s won't offer %s lap.", Monnam(u.ustuck), _mhis(u.ustuck));
        } else {
            await pline("%s has no lap.", Monnam(u.ustuck));
        }
        g.context.move = 0;
        return ECMD_OK;
    } else if (_is_pool(u.ux | 0, u.uy | 0) && !_Underwater()) {
        await You("sit in the %s.", _hliquid("water"));
        if (Upolyd && (u.umonnum | 0) === 78) {
            if (_split_mon()) {
                if ((loc && (loc.typ | 0) === FOUNTAIN)) {
                    await _dryup(u.ux | 0, u.uy | 0, true);
                }
            }
        } else {
            if (!rn2(10) && u.uarm) {
                await water_damage(u.uarm, "armor", true);
            }
            if (!rn2(10) && u.uarmf && (u.uarmf.otyp | 0) !== WATER_WALKING_BOOTS_SIT) {
                await water_damage(u.uarm, "armor", true);
            }
        }
        g.context.move = 1;
        return ECMD_TIME;
    } else if (Upolyd && (u.umonnum | 0) === 78
               && ((loc && (loc.typ | 0) === FOUNTAIN) || _is_pool(u.ux | 0, u.uy | 0))) {
        await You("sit in the %s.", _hliquid("water"));
        if (_split_mon()) {
            if ((loc && (loc.typ | 0) === FOUNTAIN)) {
                await _dryup(u.ux | 0, u.uy | 0, true);
            }
        }
        g.context.move = 1;
        return ECMD_TIME;
    }

    const objAt = g.level?.levelObjects?.[u.ux | 0]?.[u.uy | 0];
    if (objAt && !(false || false)) {
        const obj = objAt;
        if ((obj.oclass | 0) === 12) {
            await You("coil up around your %shoard.",
                ((obj.quan | 0) + _money_cnt(g.invent || null) < (u.ulevel | 0) * 1000)
                ? "meager " : "");
        } else if ((obj.otyp | 0) === 234) {
            await pline("It's probably not a good time for a picnic...");
        } else {
            /* C sit.c:450-452 — `the(xname(obj))`, and xname() deliberately
             * does NOT include the monster type for a corpse ("xname doesn't
             * include monster type for 'corpse'; cxname does", objnam.c:1925),
             * so C reads "You sit on the corpse."  This called cmd.js's local
             * partial namer _cxname_base(), whose hand-maintained otyp tables
             * have no CORPSE row, so it rendered the `object#<otyp>` fallback:
             * "You sit on the object#265."  js/objnam.js's xname() is the real
             * body — use it. */
            if (_slithy()) {
                await You("coil up around %s.", _the_str(xname(obj)));
            } else {
                await You("sit on %s.", _the_str(xname(obj)));
            }
            /* C sit.c:453-454 — `obj->otyp == CORPSE && amorphous(&mons[obj->corpsenm])`.
             * The amorphous() conjunct was missing, so EVERY corpse was squishy;
             * a lichen corpse is not amorphous and C falls through to the
             * "It's not very comfortable..." arm below (seed0107 step 85).
             * C mondata.h amorphous(ptr) = (ptr->mflags1 & M1_AMORPHOUS) != 0. */
            const M1_AMORPHOUS_SIT = 0x00000004; /* C monflag.h M1_AMORPHOUS */
            const _sitCorpsePm = (obj.corpsenm != null) ? (obj.corpsenm | 0) : -1;
            const _sitCorpseData = ((obj.otyp | 0) === 265 && _sitCorpsePm >= 0)
                ? permonstTemplate(_sitCorpsePm) : null;
            if ((obj.otyp | 0) === 265 && _sitCorpseData
                && ((_sitCorpseData.mflags1 >>> 0) & M1_AMORPHOUS_SIT) !== 0) {
                await pline("It's squishy...");
            } else if ((obj.otyp | 0) === CREAM_PIE_SIT) {
                if (!_Deaf()) {
                    _Soundeffect();
                    await pline("Squelch!");
                }
                _useupf(obj, obj.quan | 0);
            } else if (!(_Is_box(obj) || false)) {
                await pline("It's not very comfortable...");
            }
        }
    } else if (trap || (u.utrap && (u.utraptype | 0) >= TT_LAVA)) {
        if (u.utrap) {
            exercise(A_WIS, false);
            const traptype = u.utraptype | 0;
            if (traptype === TT_BEARTRAP) {
                /* C ref: sit.c:465-466 — the bear-trap message uses
                 * body_part(FOOT), not LEG (the old enum's now-fixed value
                 * for `1` was an accidental match for this literal, not a
                 * deliberate reference — see body_part enum notes above).
                 * NOTE: this `traptype === 0` dispatch itself looks shifted
                 * vs C's TT_BEARTRAP=1/TT_PIT=2/TT_WEB=3/TT_LAVA=4
                 * (you.h:340-343); that dispatch is NOT part of this
                 * packet's named defects, so it is reported, not changed. */
                await You_cant("sit down with your %s in the bear trap.",
                    body_part(FOOT));
                u.utrap = (u.utrap | 0) + 1;
            } else if (traptype === TT_PIT) {
                if (trap && (trap.ttyp | 0) === SPIKED_PIT) {
                    await You("sit down on a spike.  Ouch!");
                    await losehp(_Half_physical_damage() ? rn2(2) : 1,
                           "sitting on an iron spike", KILLED_BY);
                    exercise(A_STR, false);
                } else {
                    await You("sit down in the pit.");
                }
                u.utrap = (u.utrap | 0) + rn2(5);
            } else if (traptype === TT_WEB) {
                await You("sit in the spider web and get entangled further!");
                u.utrap = (u.utrap | 0) + rn1(10, 5);
            } else if (traptype === TT_LAVA) {
                await You("sit in the %s!", _hliquid("lava"));
                if (_Slimed()) {
                    await _burn_away_slime();
                }
                u.utrap = (u.utrap | 0) + rnd(4);
                await losehp(d(2, 10), "sitting in lava", KILLED_BY);
            } else if (traptype === TT_INFLOOR || traptype === TT_BURIEDBALL) {
                await You_cant("maneuver to sit!");
                u.utrap = (u.utrap | 0) + 1;
            }
        } else {
            await You("%s.", _Flying() ? "land" : "sit down");
            await dotrap(trap, 2);
        }
    } else if ((_Underwater() || Is_waterlevel(u.uz))
                && !_eggs_in_water()) {
        if (Is_waterlevel(u.uz)) {
            await _There("are no cushions floating nearby.");
        } else {
            await You("sit down on the muddy bottom.");
        }
    } else if (_is_pool(u.ux | 0, u.uy | 0) && !_eggs_in_water()) {
        await You("sit in the %s.", _hliquid("water"));
        if (Upolyd && (u.umonnum | 0) === 78) {
            if (_split_mon()) {
                if ((loc && (loc.typ | 0) === FOUNTAIN)) {
                    await _dryup(u.ux | 0, u.uy | 0, true);
                }
            }
        } else {
            if (!rn2(10) && u.uarm) {
                await water_damage(u.uarm, "armor", true);
            }
            if (!rn2(10) && u.uarmf && (u.uarmf.otyp | 0) !== WATER_WALKING_BOOTS_SIT) {
                await water_damage(u.uarm, "armor", true);
            }
        }
    } else if (typ === SINK) {
        await You(sit_message, _defsym_expl("sink"));
        await Your("%s gets wet.",
            _humanoid() ? "rump" : "underside");
    } else if (typ === ALTAR || IS_ALTAR(typ)) {
        await You(sit_message, _defsym_expl("altar"));
        await altar_wrath(u.ux | 0, u.uy | 0);
    } else if (typ === GRAVE) {
        await You(sit_message, _defsym_expl("grave"));
    } else if (typ === STAIRS) {
        await You(sit_message, "stairs");
    } else if (typ === 6) {
        await You(sit_message, "ladder");
    } else if (_is_lava(u.ux | 0, u.uy | 0)) {
        await You(sit_message, _hliquid("lava"));
        await _burn_away_slime();
        if (_likes_lava()) {
            await pline(_plineVFmt("The %s feels warm.", [_hliquid("lava")]));
            g.context.move = 1;
            return ECMD_TIME;
        }
        await pline(_plineVFmt("The %s burns you!", [_hliquid("lava")]));
        await losehp(d(_Fire_resistance() ? 2 : 10, 10),
               "sitting on lava", KILLED_BY);
    } else if (_is_ice(u.ux | 0, u.uy | 0)) {
        await You(sit_message, _defsym_expl("ice"));
        if (!_Cold_resistance()) {
            await pline("The ice feels cold.");
        }
    } else if (typ === 7) {
        await You(sit_message, "drawbridge");
    } else if (typ === THRONE) {
        await You(sit_message, _defsym_expl("throne"));
        await _throne_sit_effect();
    } else if (_lays_eggs()) {
        const eggResult = await _lay_an_egg();
        g.context.move = (eggResult & ECMD_TIME) ? 1 : 0;
        return eggResult;
    } else {
        await pline(_plineVFmt("Having fun sitting on the %s?", [surface(u.ux | 0, u.uy | 0)]));
    }

    g.context.move = 1;
    return ECMD_TIME;
}

/* C ref: mhitu.c:1273 gulp_blnd_check(void) — TRUE when the hero is inside an
 * engulfer whose AT_ENGL attack blinds, in which case wiping the face off does
 * NOT restore sight (the engulfer re-blinds via gulpmu()).
 *
 * The whole body is behind `!Blinded && u.uswallow`.  MEASURED, not assumed:
 * u.uswallow has exactly two writers in js/ (js/mklev.js:12629 and
 * js/potion.js:489) and both assign 0, so nothing in this tree ever engulfs the
 * hero; and gulpmu() (mhitu.c:1044) has no JS definition at all, so the block
 * could not be entered faithfully even if the flag flipped.  FALSE is what C
 * returns on every path where the hero is not engulfed, which is every path
 * this port can reach.  Reported rather than thrown: a throw here would turn a
 * future engulf into a scored-run halt, which is the shape that produced this
 * very task. */
function gulp_blnd_check() {
    const u = game.u || {};
    if (!u.uswallow)
        return false;
    /* Engulfed: the AT_ENGL/AD_BLND re-blind is unported (gulpmu).  Record it
     * for triage rather than fabricating either answer. */
    game._uncomputable_gulp_blnd_check = (game.moves | 0);
    return false;
}

/* C ref: do.c:2361 wipeoff(void) — the `#wipe' OCCUPATION callback.
 *   unsigned udelta = u.ucreamed;  long ldelta = BlindedTimeout;
 *   if (udelta > 4) udelta = 4;
 *   u.ucreamed -= udelta;
 *   if (ldelta > 4L) ldelta = 4L;
 *   incr_itimeout(&HBlinded, -ldelta);
 *   if (!HBlinded) { pline("You've got the glop off."); u.ucreamed = 0;
 *                    if (!gulp_blnd_check()) { set_itimeout(&HBlinded, 1L);
 *                                              make_blinded(0L, TRUE); }
 *                    return 0; }
 *   else if (!u.ucreamed) { Your("%s feels clean now.", body_part(FACE));
 *                           return 0; }
 *   return 1;                      // still busy
 *
 * FOUR points of C to keep exactly:
 *   - the two deltas are clamped INDEPENDENTLY (u.ucreamed by 4, BlindedTimeout
 *     by 4), so a hero whose blindness outlasts the goop keeps wiping;
 *   - `!HBlinded` tests the WHOLE intrinsic field, not BlindedTimeout;
 *   - the set_itimeout(&HBlinded, 1L) immediately before make_blinded(0L, TRUE)
 *     is what makes make_blinded see a TRANSITION and speak: without it
 *     u_could_see is already true and the "You can see again." arm is skipped;
 *   - it returns 0 on BOTH terminating arms, and 0 is what clears go.occupation.
 *
 * RNG: none, on any arm.  Every leaf inside seed0108's step-62 bucket comes
 * from the two world turns the occupation spans, not from this callback.
 *
 * seed0108 is the corpus case and it terminates on the FIRST callback: the pie
 * set u.ucreamed = blindinc = rnd(25) = 3 and HBlinded = 3, so udelta = ldelta
 * = 3, both go to zero, and C's topline is "You've got the glop off.  You can
 * see again." — the two plines joined by the topline joiner, no --More--. */
async function wipeoff() {
    const u = game.u = game.u || {};
    let udelta = (u.ucreamed | 0);
    let ldelta = BlindedTimeout();

    if (udelta > 4) udelta = 4;
    u.ucreamed = (u.ucreamed | 0) - udelta;
    if (ldelta > 4) ldelta = 4;
    incr_HBlinded(-ldelta);

    if (!HBlinded()) {
        await pline("You've got the glop off.");
        u.ucreamed = 0;
        if (!gulp_blnd_check()) {
            set_HBlinded(1);
            make_blinded(0, true);
        }
        return 0;
    } else if (!u.ucreamed) {
        await Your("%s feels clean now.", body_part(FACE));
        return 0;
    }
    return 1; /* still busy */
}

/* C ref: do.c:2390 dowipe() — the `#wipe' command.
 *   if (u.ucreamed) { Sprintf(buf, "wiping off your %s", body_part(FACE));
 *                     set_occupation(wipeoff, buf, 0); return ECMD_TIME; }
 *   Your("%s is already clean.", body_part(FACE));
 *   return ECMD_TIME;
 * BOTH arms return ECMD_TIME, so #wipe always costs a turn even when there is
 * nothing to wipe off.  RNG-free at this level.
 *
 * HISTORY, because it is the whole lesson of this function: this arm used to
 * `throw`, parked on "no corpus session is creamed when it types #wipe
 * (u.ucreamed has no writer in this port either)".  That was TRUE until
 * use_cream_pie (:10880) landed as the field's first writer twenty minutes
 * later, and seed0108 types #wipe seven steps after it eats the pie — so the
 * scored run went from 303 emitted frames to 62.  Landing the first writer of a
 * never-set field arms every reader parked on its absence.
 *
 * The three pieces named by that note all land together here: wipeoff() above,
 * make_blinded's regaining-sight talk arm (js/zap.js), and the js/allmain.js
 * occupation driver arm — allmain gates its driver per callback IDENTITY
 * (`g.occupation === eatfood`, `=== dig`, `=== picklock`, ...), so an occupation
 * that is merely SET is never pumped.  wipeoff is exported for that arm. */
async function dowipe() {
    const u = game.u || {};
    if (u.ucreamed) {
        /* C do.c:2393-2396 — Sprintf(buf, "wiping off your %s", body_part(FACE))
         * then set_occupation(wipeoff, buf, 0).  xtime 0, so this is the
         * untimed arm: wipeoff() times itself out by returning 0. */
        set_occupation(wipeoff, `wiping off your ${body_part(FACE)}`, 0);
        return ECMD_TIME;
    }
    await Your("%s is already clean.", body_part(FACE));
    return ECMD_TIME;
}
export { wipeoff };

