    449: 'yellowish brown', 450: 'yellowish brown', 451: 'black', 452: 'white',
    453: 'yellow', 454: 'red', 455: 'violet', 456: 'red', 457: 'violet',
    458: 'black', 459: 'orange', 460: 'green',
