function _look_here_dfeature_line(x, y) {
    /* C invent.c:4181-4183 — dfeature_at, with Underwater suppressing "pool of
     * water".  look.js's body, not cmd.js's throwing one (see look.js:169). */
    const _df = look_dfeature_at(x | 0, y | 0);
    let dfeature = _df ? _df.text : null;
    if (!dfeature) return null;
    if (dfeature === 'pool of water' && Underwater()) return null;
    /* C invent.c:4224-4235: "molten lava", "iron bars", plain "ice",
     * "frozen *" and "* ice" take no article; everything else gets an(). */
    const p = dfeature.indexOf(' ');
    const article0 = dfeature === 'molten lava' || dfeature === 'iron bars'
        || dfeature === 'ice' || dfeature.startsWith('frozen ')
        || (p >= 0 && dfeature.slice(p).toLowerCase() === ' ice');
    const phrase = article0 ? dfeature : an(dfeature);
    /* C invent.c:4238 — `vtense(dfeature, "are")` is evaluated AFTER
     * invent.c:4236 has already reassigned `dfeature = an(dfeature)`, so the
     * subject vtense() sees carries its article.  That matters: vtense()'s very
     * first test (objnam.c) is `if (!strncmpi(subj, "a ", 2) || !strncmpi(subj,
     * "an ", 3)) goto sing;`.  Handed the RAW feature instead, vtense walks for
     * " of "/" from "/" called " and takes the character before it as the head
     * noun -- so "branch staircase up to the Dungeons of Doom" ends on the 's'
     * of "Dungeons" and reads PLURAL: "There are a branch staircase up to the
     * Dungeons of Doom here."  Pass the articled phrase, as C does. */
    return `There ${vtense(phrase, 'are')} ${phrase} here.`;
}

