/* C hack.c:97-103 — obj_to_any(struct obj *obj): wrap an obj pointer in the
 * shared `anything` union.
 *     anything *
 *     obj_to_any(struct obj *obj)
 *     {
 *         gt.tmp_anything = cg.zeroany;
 *         gt.tmp_anything.a_obj = obj;
 *         return &gt.tmp_anything;
 *     }
 * gt.tmp_anything is a single FILE-STATIC union that every *_to_any() shares
 * and overwrites, and the return is its address — so the caller's pointer goes
 * stale the moment any other _to_any() runs.  Reproduced exactly, in the same
 * shape as the sibling long_to_any (cmd.js:15625) and monst_to_any
 * (cmd.js:17610) ports, so all three keep aliasing ONE object as in C. */
export function obj_to_any(obj) {
    const g = game;
    if (!g.gt) g.gt = {};
    if (!g.cg) g.cg = {};
    if (!g.cg.zeroany) g.cg.zeroany = {};
    // C: gt.tmp_anything = cg.zeroany;
    g.gt.tmp_anything = { ...g.cg.zeroany };
    // C: gt.tmp_anything.a_obj = obj;
    g.gt.tmp_anything.a_obj = obj;
    /* JS timer elements compare the inactive union arm too; use the same
     * canonical object-wrapper shape as timeout.js/mklev.js. */
    g.gt.tmp_anything.a_long = null;
    // C: return &gt.tmp_anything;
    return g.gt.tmp_anything;
}
/* C artifact.c:730-892 set_artifact_intrinsic(otmp, on, wp_mask).
 *
 * Was a throwing stub, and the comment in setuwep() below asserted the W_WEP
 * call site was "not reached by any captured record (oartifact is always 0 in
 * this packet's corpus)".  seed0361-archeologist-tour wields a wished
 * Grayswandir (artilist[14], spfx SPFX_RESTR|SPFX_HALRES), so C sets
 * EHalluc_resistance |= W_WEP there and prints "You resist hallucinations
 * because of Grayswandir." in ^X enlightenment; this port printed nothing.
 *
 * The artilist[] columns this needs (cspfx, defn.adtyp, cary.adtyp, mtype,
 * inv_prop) live in js/attrib.js beside the spfx column that was already
 * there, so there is one artilist[] in the tree rather than a second copy.
 *
 * `mask` in C is a `long *` into u.uprops[].extrinsic; here it is the prop
 * INDEX, with 0 standing for C's NULL (prop 0 is not a real property).
 */
export function set_artifact_intrinsic(otmp, on, wp_mask) {
    const g = game;
    const u = g.u || (g.u = {});
    let maskProp = 0;
    const oart = get_artifact(otmp);

    if (oart === ART_NONARTIFACT)
        return;

    /* effects from the defn field */
    const dtyp = (wp_mask !== W_ART) ? arti_defn_adtyp(oart) : arti_cary_adtyp(oart);

    if (dtyp === AD_FIRE_ART) maskProp = FIRE_RES;
    else if (dtyp === AD_COLD_ART) maskProp = COLD_RES;
    else if (dtyp === AD_ELEC_ART) maskProp = SHOCK_RES;
    else if (dtyp === AD_MAGM_ART) maskProp = ANTIMAGIC;
    else if (dtyp === AD_DISN_ART) maskProp = DISINT_RES;
    else if (dtyp === AD_DRST_ART) maskProp = POISON_RES;
    else if (dtyp === AD_DRLI_ART) maskProp = DRAIN_RES;

    if (maskProp && wp_mask === W_ART && !on) {
        /* find out if some other artifact also confers this intrinsic;
           if so, leave the mask alone */
        for (let obj = u.invent || g.invent; obj; obj = obj.nobj) {
            if (obj !== otmp && obj.oartifact) {
                const art = get_artifact(obj);
                if (art !== ART_NONARTIFACT && arti_cary_adtyp(art) === dtyp) {
                    maskProp = 0;
                    break;
                }
            }
        }
    }
    if (maskProp)
        _sai_set(maskProp, on, wp_mask);

    /* intrinsics from the spfx field; there could be more than one */
    let spfx = (wp_mask !== W_ART) ? arti_spfx(oart) : arti_cspfx(oart);
    if (spfx && wp_mask === W_ART && !on) {
        /* don't change any spfx also conferred by other artifacts */
        for (let obj = u.invent || g.invent; obj; obj = obj.nobj)
            if (obj !== otmp && obj.oartifact) {
                const art = get_artifact(obj);
                if (art !== ART_NONARTIFACT)
                    spfx &= ~arti_cspfx(art);
            }
    }

    if (spfx & SPFX_SEARCH_ART)
        _sai_set(SEARCHING, on, wp_mask);
    if (spfx & SPFX_HALRES_ART) {
        /* C: make_hallucinated((long) !on, program_state.restoring ? FALSE
         *                      : TRUE, wp_mask) — "make_hallucinated must
         *    (re)set the mask itself to get the display right".
         * js/potion.js's make_hallucinated() is async ONLY because of the
         * trailing `await pline()` in its `changed` block, and on the mask
         * branch `changed` requires the hero to be hallucinating at this
         * instant.  C's three callers of set_artifact_intrinsic (setworn,
         * freeinv, addinv) are synchronous voids, so this is deliberately not
         * awaited: the mask update and the see_* / update_inventory redraws
         * in that block still run in call order, and only that one pline would
         * be deferred to a microtask.  No corpus session reaches it (the sole
         * HALRES artifact is Grayswandir). */
        void make_hallucinated(on ? 0 : 1, !g.program_state?.restoring, wp_mask);
    }
    if (spfx & SPFX_ESP_ART) {
        _sai_set(TELEPAT, on, wp_mask);
        recalc_telepat_range();
        see_monsters();
    }
    if (spfx & SPFX_STLTH_ART)
        _sai_set(STEALTH, on, wp_mask);
    if (spfx & SPFX_REGEN_ART)
        _sai_set(REGENERATION_ART, on, wp_mask);
    if (spfx & SPFX_TCTRL_ART)
        _sai_set(TELEPORT_CONTROL, on, wp_mask);
    if (spfx & SPFX_WARN_ART) {
        const m2 = spec_m2(otmp);
        if (m2) {
            _sai_set(WARN_OF_MON, on, wp_mask);
            const wt = (g.context ||= {}).warntype ||= { obj: 0, polyd: 0, speciesidx: 0 };
            if (on)
                wt.obj = (wt.obj | 0) | m2;
            else
                wt.obj = (wt.obj | 0) & ~m2;
            see_monsters();
        } else {
            _sai_set(WARNING, on, wp_mask);
        }
    }
    if (spfx & SPFX_EREGEN_ART)
        _sai_set(ENERGY_REGENERATION_ART, on, wp_mask);
    if (spfx & SPFX_HSPDAM_ART)
        _sai_set(HALF_SPDAM_ART, on, wp_mask);
    if (spfx & SPFX_HPHDAM_ART)
        _sai_set(HALF_PHDAM_ART, on, wp_mask);
    if (spfx & SPFX_XRAY_ART) {
        /* this assumes that no one else is using xray_range */
        u.xray_range = on ? 3 : -1;
        g.vision_full_recalc = 1;
    }
    if ((spfx & SPFX_REFLECT_ART) && (wp_mask & W_WEP_C))
        _sai_set(REFLECTING, on, wp_mask);
    if (spfx & SPFX_PROTECT_ART)
        _sai_set(PROTECTION_ART, on, wp_mask);

    if (wp_mask === W_ART && !on && arti_inv_prop(oart)) {
        /* might have to turn off invoked power too */
        const ip = arti_inv_prop(oart);
        if (ip <= LAST_PROP_ART
            && (((u.uprops?.[ip]?.extrinsic) | 0) & W_ARTI_FW))
            void arti_invoke(otmp);
    }

    if (wp_mask === W_WEP_C && is_art(otmp, ART_SUNSWORD))
        _sai_set(BLND_RES_ART, on, wp_mask);
}
/* u.uprops[p].extrinsic |= / &= ~wp_mask, with worn.c's BSS-zero-init shape. */
function _sai_set(propidx, on, wp_mask) {
    const u = game.u || (game.u = {});
    if (!u.uprops)
        u.uprops = {};
    if (!u.uprops[propidx])
        u.uprops[propidx] = { intrinsic: 0, extrinsic: 0, blocked: 0 };
    const p = u.uprops[propidx];
    p.extrinsic = on ? ((p.extrinsic | 0) | wp_mask) : ((p.extrinsic | 0) & ~wp_mask);
}
/* monattk.h AD_* and artifact.h SPFX_* — the subset set_artifact_intrinsic
 * branches on.  Suffixed to avoid colliding with this file's other locals. */
const AD_MAGM_ART = 1, AD_FIRE_ART = 2, AD_COLD_ART = 3, AD_DISN_ART = 5,
      AD_ELEC_ART = 6, AD_DRST_ART = 7, AD_DRLI_ART = 15;
const SPFX_SEARCH_ART = 0x00000200, SPFX_HALRES_ART = 0x00000800,
      SPFX_ESP_ART = 0x00001000, SPFX_STLTH_ART = 0x00002000,
      SPFX_REGEN_ART = 0x00004000, SPFX_EREGEN_ART = 0x00008000,
      SPFX_HSPDAM_ART = 0x00010000, SPFX_HPHDAM_ART = 0x00020000,
      SPFX_TCTRL_ART = 0x00040000, SPFX_WARN_ART = 0x00000020,
      SPFX_XRAY_ART = 0x02000000, SPFX_REFLECT_ART = 0x04000000,
      SPFX_PROTECT_ART = 0x08000000;
/* prop.h numbers this file does not already import under these names. */
const REGENERATION_ART = 57, ENERGY_REGENERATION_ART = 58,
      HALF_SPDAM_ART = 55, HALF_PHDAM_ART = 56, PROTECTION_ART = 59,
      BLND_RES_ART = 38, LAST_PROP_ART = 68;
/* C questpgr.c:66-70 is_quest_artifact(otmp).  This was a throwing stub whose
 * comment said it was "not exported from js/objnam.js"; it is (objnam.js:551),
 * and js/questpgr.js has been importing that one all along.  Two same-named
 * bodies where one throws is the file-local-stub-shadows-real-port shape: the
 * throwing one won inside this file, so freeinv_core() and addinv_core1()
 * could not run C's `else if (obj->oartifact)` arm at all. */
export function is_quest_artifact(otmp) {
    return _objnam_is_quest_artifact(otmp);
}
