// C ref: hacklib.c:532 visctrl(c) — return string representation of a
// non-printable char. C rotates a static buffer pool so callers can hold
// several results; JS strings are values so we return directly.
export function visctrl(c) {
    let ccc = '';
    if ((c & 0x80) !== 0) {
        ccc += 'M';
        ccc += '-';
    }
    c = c & 0x7f;
    if (c < 0x20) {
        ccc += '^';
        ccc += String.fromCharCode(c | 0x40);
    } else if (c === 0x7f) {
        ccc += '^';
        ccc += String.fromCharCode(c & ~0x40);
    } else {
        ccc += String.fromCharCode(c);
    }
    return ccc;
}

