function is_ice(x, y) {
    if (!isok(x, y)) return false;
    const loc = game.level?.at?.(x, y);
    if (!loc) return false;
    const t = loc.typ | 0;
    return t === ICE
        || (t === DRAWBRIDGE_UP && ((loc.drawbridgemask | 0) & DB_UNDER) === DB_ICE);
}
