/* C mondata.h grounded(ptr) — not a flyer/floater/clinger and not amorphous
 * air.  Every un-polymorphed corpus hero is grounded; the two flags that could
 * lift one (M1_FLY / M1_FLOAT) are read here rather than assumed. */
/* monflag.h:85 — M1_FLY covers both flying and floating; v5 has no separate
 * M1_FLOAT bit.  0x10/0x20 are wall-walking/clinging flags. */
const _SMD_M1_FLY = 0x00000001;
function _smd_grounded(ptr) {
    return !ptr || (((ptr.mflags1 | 0) & _SMD_M1_FLY) === 0);
}

/* C ref: hack.c:1884-1919 swim_move_danger(x, y) — "Is it dangerous for hero to
 * move to x,y due to water or lava?".  Ported whole; it was missing entirely,
 * so a hero who walked at a lava pool simply walked in.
 *
 * ParanoidSwim is ON by default: options.c:7173 seeds
 * flags.paranoia_bits = PARANOID_PRAY | PARANOID_SWIM | PARANOID_TRAP, and no
 * corpus nethackrc clears it — the same reasoning (and the same constant) the
 * ParanoidTrap confirm above already relies on.
 *
 * Measured on seed4500-knight-coverage step 327: C prints "You avoid stepping
 * into the molten lava." plus handle_tip(TIP_SWIM)'s follow-up and does NOT
 * move; JS printed nothing, stepped in, and mismatched every frame after. */
async function swim_move_danger(x, y) {
    const u = game.u || {};
    const newtyp = _u_simple_floortyp(x, y);
    const liquid_wall = IS_WATERWALL(newtyp) || newtyp === LAVAWALL;
    const _up = u.uprops || {};
    const Stunned = (_up.STUNNED?.intrinsic) || 0;
    const Confusion = (_up.CONFUSION?.intrinsic) || 0;
    const loc = _levlAt(x, y);
    /* PARANOID_SWIM — see the block comment above. */
    const ParanoidSwim = true;

    if (Underwater() && (flooreffects_is_pool(x, y) || IS_WATERWALL(newtyp)))
        return false;

    if (newtyp !== _u_simple_floortyp(u.ux, u.uy)
        && !Stunned && !Confusion && loc && (loc.seenv | 0)
        && (flooreffects_is_pool(x, y) || flooreffects_is_lava(x, y)
            || liquid_wall)) {
        if ((flooreffects_is_pool(x, y) && !_Known_wwalking())
            /* is_lava(ux,uy): don't move onto/over lava with known
               lava-walking because it isn't completely safe, but do
               continue to move over lava if already doing so */
            || (flooreffects_is_lava(x, y) && !_Known_lwalking()
                && !flooreffects_is_lava(u.ux, u.uy))
            || liquid_wall) {
            if (game.context?.nopick) {
                /* moving with m-prefix */
                _swim_arm_tip();
                return false;
            } else if (ParanoidSwim || liquid_wall) {
                await pline(`You avoid ${ing_suffix(u_locomotion("step"))} into the ${waterbody_name(x, y)}.`);
                await handle_tip(TIP_SWIM);
                return true;
            }
        }
    }
    return false;
}
/* C hack.c:1909 `svc.context.tips |= (1 << TIP_SWIM);` — the m-prefix arm marks
 * the tip as already-given without printing it, so a later non-prefixed bump
 * stays silent.  handle_tip() reads the same game.context.tips array. */
function _swim_arm_tip() {
    if (!game.context.tips)
        game.context.tips = [];
    game.context.tips[TIP_SWIM] = true;
}

/* C rm.h:2089 DB_MOAT — not in this file's const.js import list. */
const DB_MOAT_WB = 0;
/* C ref: rm.h:133 SURFACE_AT(x,y) and dbridge.c:115-128 db_under_typ(mask).
 * cmd.js's surface() documents db_under_typ as a known gap; waterbody_name is
 * the one caller that needs it, so it is ported here rather than left open. */
function _waterbody_surface_typ(x, y) {
    const loc = _levlAt(x, y);
    if (!loc) return STONE;
    const typ = loc.typ | 0;
    if (typ !== DRAWBRIDGE_UP) return typ;
    switch ((loc.drawbridgemask | 0) & DB_UNDER) {
    case DB_ICE:  return ICE;
    case DB_LAVA: return LAVAPOOL;
    case DB_MOAT_WB: return MOAT;
    default:      return STONE;
    }
}

/* C ref: invent.c:646 unsortloot — free sortloot()'s allocated Loot array */
export function unsortloot(loot_array_p) {
    if (loot_array_p) {
        /* free((genericptr_t) *loot_array_p) — no-op in JS */
        /* *loot_array_p = (Loot *) 0 */
        loot_array_p.length = 0; /* null the array */
    }
}

/* C ref: pray.c:2524 u_gname(void) -> align_gname(u.ualign.type).
 * Harvested from fleet proposal fleet:proposal:packet:u_gname:1782582156297
 * (deepseek-v4-pro, 2026-06-27), s3://nethack/fleet-out/packet-porter/packet-u_gname-1782582156297/cmd.js */
export function u_gname() {
    return align_gname(game.u.ualign.type);
}

/* C ref: cmd.c:3894 key2txt(uchar c, char *txt) -- C fills the caller buffer and
 * returns it; the JS port returns the string (txt kept for signature parity).
 * Harvested from fleet proposal fleet:proposal:packet:key2txt:1782594852141
 * (deepseek-v4-pro, 2026-06-27), s3://nethack/fleet-out/packet-porter/packet-key2txt-1782594852141/cmd.js */
export function key2txt(c, txt) {
    if (c === 32) /* ' ' */
        return "<space>";
    else if (c === 27) /* '\033' */
        return "<esc>";
    else if (c === 10) /* '\n' */
        return "<enter>";
    else if (c === 127) /* '\177' */
        return "<del>";
    else
        return visctrl(c);
}
